(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-verb-forms":{"title":"Verb Forms","topic":"Grammar & Usage","questions":[{"id":"grammar-verb-forms-q0001","version":2,"contentHash":"sha256:98cd22e46b9a9127f4cf1a546b566254c5db275984d61a55e3ed9e9fdcc03f66","question":"What is the past tense of 'go'?","choices":["goed","went","gone","going"],"correct":1,"explanation":{"correct":"Answer: went. The verb 'go' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show past action. The correct form is 'went'.","incorrect":[{"choice":"goed","category":"incorrect past tense","reason":"Adding '-ed' to 'go' is not correct because 'go' is an irregular verb. Regular verbs add '-ed', but irregular verbs change their form completely."},"",{"choice":"gone","category":"past participle error","reason":"'Gone' is the past participle of 'go' and is used with helper verbs like 'has' or 'have'. It cannot be used alone as the simple past tense of the verb."},{"choice":"going","category":"present participle error","reason":"'Going' is the present participle, which describes an action currently happening or in progress. It does not indicate that the action already finished."}]},"studyAid":{"definition":"Irregular verbs are verbs that change their spelling to show past tense rather than just adding '-ed'. You must memorize these special forms because they don't follow the normal pattern.","example":"eat becomes ate (not eated), run becomes ran (not runned), see becomes saw (not seed).","strategyClue":"Ask yourself if the action is currently happening, has already finished, or needs a helper verb. If the word ends in '-ing', it is ongoing; if it is an irregular verb, it will likely have a unique spelling for the past tense.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0002","version":2,"contentHash":"sha256:fa15479604248e998469bfd5d47a46ec2c97341aec7023dade26f01393fefe50","question":"What is the past participle of 'eat'?","choices":["ate","eaten","eated","eating"],"correct":1,"explanation":{"correct":"Answer: eaten. The past participle of 'eat' is 'eaten'. This form is used with helper verbs like 'has', 'have', or 'had' to form perfect verb tenses.","incorrect":[{"choice":"ate","category":"simple past tense","reason":"'Ate' is the simple past tense of 'eat', which describes an action that finished in the past. It is not used with helper verbs."},"",{"choice":"eated","category":"irregular verb error","reason":"'Eated' is not a real word. 'Eat' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show past tense."},{"choice":"eating","category":"present participle","reason":"'Eating' is the present participle, used to describe actions that are currently happening or that happen over a period of time."}]},"studyAid":{"definition":"The past participle of an irregular verb is the form used after helper words like 'have', 'has', or 'had'.","example":"I have eaten lunch. She has eaten already. (Correct) vs. I have ate lunch. (Incorrect)","strategyClue":"Test the word by placing 'I have' in front of it. If the phrase makes sense, you have likely found the correct past participle.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0003","version":2,"contentHash":"sha256:69e0559723331bff73d98fafabe082a9a32df0a0835f9c8add6c2c9b455ae92d","question":"Which is the correct form: 'She has ___ the cake.'","choices":["bake","baked","baking","bakes"],"correct":1,"explanation":{"correct":"Answer: baked. The verb phrase 'has baked' uses the present perfect tense, which requires the past participle form of the verb after 'has'.","incorrect":[{"choice":"bake","category":"base form error","reason":"The base form 'bake' does not fit after 'has'. When using helping verbs like 'has', you must use the past participle form to show the action is completed."},"",{"choice":"baking","category":"present participle error","reason":"The form 'baking' is a present participle. To use it after 'has', you would also need the helping verb 'been' (has been baking), which is not present in this sentence."},{"choice":"bakes","category":"third person singular","reason":"'Bakes' is the simple present tense form for habitual actions. It cannot follow the helping verb 'has' in this sentence structure."}]},"studyAid":{"definition":"The present perfect tense is formed by using 'has' or 'have' plus the past participle of a verb to describe an action that happened in the past.","example":"He has walked, She has finished, They have eaten.","strategyClue":"Look at the helping verb 'has' before the blank. Test if the word can follow 'has' naturally by saying 'I have [word]' out loud to see which form sounds like a completed action.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0004","version":2,"contentHash":"sha256:619dd40ab98547cf6606557c35545792db7cbc7af66c243d27613fb94c9f9069","question":"What is the simple past of 'run'?","choices":["runned","ran","run","running"],"correct":1,"explanation":{"correct":"Answer: ran. The verb 'run' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show the past tense. You must change the spelling to 'ran' to describe an action that already happened.","incorrect":[{"choice":"runned","category":"incorrect verb conjugation","reason":"Adding '-ed' to 'run' is incorrect because 'run' is an irregular verb. English does not use 'runned' to talk about the past."},"",{"choice":"run","category":"present tense form","reason":"'Run' is the present tense form. Using it here makes the sentence sound like the action is happening right now instead of in the past."},{"choice":"running","category":"present participle","reason":"'Running' describes an action that is currently in progress. It requires a helping verb like 'is' or 'was' and does not work as a simple past tense verb on its own."}]},"studyAid":{"definition":"Irregular verbs are special words that do not follow the 'add -ed' rule to show the past. You must memorize their specific past tense forms.","example":"eat -> ate, go -> went, run -> ran","strategyClue":"Ask yourself: 'Did this happen yesterday?' If it did, check if you are trying to add '-ed' to a word that sounds wrong. If you are, you are likely dealing with an irregular verb that changes its spelling completely.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0005","version":2,"contentHash":"sha256:779e1b0bebf4a9e52ea646fcfd4230dd5a3ed9e575dbbb83843851fed6d9fdef","question":"Which is correct: 'They ___ playing soccer.'","choices":["is","are","was","be"],"correct":1,"explanation":{"correct":"Answer: are. The subject 'They' is plural, so it requires the plural form of the helping verb 'to be', which is 'are'.","incorrect":[{"choice":"is","category":"subject-verb disagreement","reason":"'Is' is used for singular subjects like 'he' or 'she'. Since 'they' refers to more than one person, 'is' does not match."},"",{"choice":"was","category":"singular past tense","reason":"'Was' is a singular verb. Because 'they' is plural, you must use a plural verb form even when talking about the past."},{"choice":"be","category":"missing helping verb","reason":"'Be' is the base form of the verb. It does not work as a helping verb for 'they' because it hasn't been conjugated to match the subject."}]},"studyAid":{"definition":"A subject and its verb must agree in number; plural subjects (like 'they', 'we', or 'you') need plural verb forms, while singular subjects need singular forms.","example":"They are running. She is running. We are jumping. He is jumping.","strategyClue":"Identify if the subject is singular (one person/thing) or plural (more than one). Once you know the count, choose the verb form that matches that group.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0006","version":2,"contentHash":"sha256:838752f89f6bb2adf72ce2aec366a6ee243247b0284c3d34a7b5693f563e9ac2","question":"What is the past tense of 'bring'?","choices":["bringed","brought","brung","bringing"],"correct":1,"explanation":{"correct":"Answer: brought. The verb 'bring' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show past action. Its past tense form is simply 'brought'.","incorrect":[{"choice":"bringed","category":"incorrect verb conjugation","reason":"Although adding '-ed' works for many words, 'bring' is irregular. 'Bringed' is not a word in standard English."},"",{"choice":"brung","category":"nonstandard verb form","reason":"'Brung' is often heard in casual speech, but it is not the correct past tense form. Use 'brought' to keep your writing formal and clear."},{"choice":"bringing","category":"present participle","reason":"'Bringing' is the present participle, which shows an action that is currently happening. It cannot stand alone as a past tense verb."}]},"studyAid":{"definition":"Regular verbs add '-ed' to show past tense, but irregular verbs change their spelling in unique ways.","example":"walk/walked (regular), buy/bought (irregular), see/saw (irregular)","strategyClue":"Try saying the word in a sentence starting with 'Yesterday, I...'. If the word sounds like it fits the 'ed' rule but sounds strange, look for the special irregular form.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0007","version":2,"contentHash":"sha256:20d4abe4b4ad50fc3f8067fdd389e4a597e5035d1338974eacdb40ecf8731880","question":"Which is correct: 'He ___ to school every day.'","choices":["walk","walks","walking","walked"],"correct":1,"explanation":{"correct":"Answer: walks. Because the subject 'He' is singular and the action happens 'every day' (present simple tense), you must add an 's' to the verb.","incorrect":[{"choice":"walk","category":"subject-verb agreement","reason":"The verb 'walk' is for plural subjects like 'they' or 'we.' Since 'He' is singular, you need to add an 's' to make it 'walks'."},"",{"choice":"walking","category":"missing helping verb","reason":"'Walking' is an action that needs a helping verb like 'is' or 'was' to make sense. Without a helping verb, it cannot stand alone as the main action."},{"choice":"walked","category":"incorrect verb tense","reason":"'Walked' describes something that already happened in the past. Since the sentence mentions 'every day,' we need to use the present tense."}]},"studyAid":{"definition":"When the subject is singular (he, she, it) and the action happens now or regularly, add 's' or 'es' to the end of the verb.","example":"He runs fast. They run fast. She eats lunch. We eat lunch.","strategyClue":"Identify the subject of the sentence and determine if it represents one person or multiple people, then check if the time signal (like 'every day') points to the present.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0008","version":2,"contentHash":"sha256:189a15fa3381f05298abae6e52e5a9ed4d53507eee38def6ce76dfb10d78fbdf","question":"What is the past participle of 'write'?","choices":["wrote","written","writed","writing"],"correct":1,"explanation":{"correct":"Answer: written. Irregular verbs do not follow the standard -ed rule. The past participle of 'write' is 'written', which is used after helping verbs like 'have', 'has', or 'had'.","incorrect":[{"choice":"wrote","category":"simple past tense","reason":"'Wrote' is the simple past tense (e.g., 'I wrote a letter'), not the past participle. Participles usually require a helping verb."},"",{"choice":"writed","category":"incorrect verb conjugation","reason":"'Writed' is not a real word. Because 'write' is an irregular verb, it does not use the -ed suffix to form its past participle."},{"choice":"writing","category":"present participle","reason":"'Writing' is the present participle or gerund form. It describes an action happening now, not a completed action."}]},"studyAid":{"definition":"The past participle is a verb form used with 'have', 'has', or 'had' to show completed actions. Many common verbs are 'irregular' and change their spelling instead of adding -ed.","example":"I have written (not writed), She has eaten (not eated), They have gone (not goed).","strategyClue":"Try putting the word 'have' before the choice. If 'I have [word]' sounds like a complete, correct sentence, you have likely found the past participle.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0009","version":2,"contentHash":"sha256:1889d371932de0df6f7ad72dedce9e816045b739e0b4643faacc448f661a1506","question":"Which is correct: 'We ___ finished our homework.'","choices":["has","have","had","Both B and C"],"correct":3,"explanation":{"correct":"Answer: Both B and C. The pronoun 'we' is plural, so it requires the plural helping verbs 'have' (present perfect) or 'had' (past perfect) to form the sentence correctly.","incorrect":[{"choice":"has","category":"subject-verb disagreement","reason":"The verb 'has' is singular, but the subject 'we' is plural. Always pair plural subjects with 'have' or 'had'."},{"choice":"have","reason":"\"have\" does not match the tense, helping verb, or subject-verb pattern required here."},{"choice":"had","reason":"\"had\" does not match the tense, helping verb, or subject-verb pattern required here."},""]},"studyAid":{"definition":"A helping verb must match the number of the subject. Use 'has' with singular subjects (he/she/it) and 'have' or 'had' with plural subjects (we/they/you).","example":"He has eaten. / We have eaten. / We had eaten.","strategyClue":"Identify the subject first. If the subject is 'we', test each verb choice by pairing it with that subject to see which combinations sound correct in standard English.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0010","version":2,"contentHash":"sha256:e38b011d667bd7d73da38105ca944353344315408624f3c7d52a1b81a4265318","question":"What is the simple past of 'begin'?","choices":["begined","began","begun","beginning"],"correct":1,"explanation":{"correct":"Answer: began. 'Begin' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show the past tense. The correct past tense form is 'began'.","incorrect":[{"choice":"begined","category":"incorrect verb conjugation","reason":"Because 'begin' is an irregular verb, you cannot simply add '-ed' to the end. 'Begined' is not a word in standard English."},"",{"choice":"begun","category":"past participle misuse","reason":"'Begun' is the past participle of 'begin', which is used after helping verbs like 'have' or 'had' (e.g., 'I have begun'), not as the simple past tense by itself."},{"choice":"beginning","category":"incorrect verb form","reason":"'Beginning' is the present participle form used for actions happening now or to describe an ongoing state; it does not indicate that the action happened in the past."}]},"studyAid":{"definition":"Irregular verbs are verbs that change their spelling to show the past tense instead of just adding '-ed'. You must memorize these special forms because they do not follow the normal pattern.","example":"Correct: I began the race. Incorrect: I begined the race. Correct: I have begun. Incorrect: I have began.","strategyClue":"Ask yourself if the action happened already, then recall if the verb is a 'regular' word that adds '-ed' or a 'special' word that changes its spelling. If you aren't sure, try to recall how you have heard the word used in past-tense stories or sentences.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0011","version":2,"contentHash":"sha256:e7f3c92023e242167152412d6e7e70c8c8207730fc57bb5780916dbba3e7d59c","question":"Which is correct: 'She ___ singing when I arrived.'","choices":["is","was","were","be"],"correct":1,"explanation":{"correct":"Answer: was. The sentence is in the past tense because of the word 'arrived.' 'Was' is the correct singular past tense verb to match 'She'.","incorrect":[{"choice":"is","category":"present tense verb","reason":"The word 'arrived' tells us the sentence happened in the past. 'Is' is present tense, which does not match the rest of the sentence."},"",{"choice":"were","category":"plural past tense","reason":"'Were' is used for plural subjects like 'they' or 'we.' Because the subject is the singular 'She,' 'were' is incorrect."},{"choice":"be","category":"base verb form","reason":"'Be' is the base form of the verb. It needs to be changed to 'was' to correctly show the action happening in the past."}]},"studyAid":{"definition":"Verbs must match their subject (singular or plural) and the time (tense) of the sentence. 'Was' is the singular past tense form of 'to be'.","example":"He was happy. (past) They were happy. (past) She is happy. (present)","strategyClue":"Look for time signal words like 'arrived' or 'yesterday' to identify if the sentence is happening now or happened before, then choose the verb that matches both the time and the subject count.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0012","version":2,"contentHash":"sha256:5e9b84fbf04a747bda8c40cb331465d49d50b4b1bc3f0950b176c3ad2762b8f6","question":"What is the past tense of 'fly'?","choices":["flyed","flew","flown","flying"],"correct":1,"explanation":{"correct":"Answer: flew. The verb 'fly' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show past tense. The correct past tense form for 'fly' is 'flew'.","incorrect":[{"choice":"flyed","category":"incorrect irregular verb","reason":"We cannot add '-ed' to 'fly' because it is an irregular verb. Regular verbs add '-ed', but irregular verbs change their spelling entirely."},"",{"choice":"flown","category":"past participle misuse","reason":"'Flown' is the past participle, which is used with helping verbs like 'has' or 'had'. It cannot stand alone as the simple past tense of the verb."},{"choice":"flying","category":"present participle misuse","reason":"'Flying' is the present participle form used to describe an action happening right now. It does not show that the action already finished in the past."}]},"studyAid":{"definition":"Irregular verbs are verbs that change their spelling or sound to show past tense, rather than just adding '-ed'. You must memorize these special forms because they do not follow the normal pattern.","example":"eat becomes ate (not eated), go becomes went (not goed), fly becomes flew (not flyed).","strategyClue":"Think about whether the verb is a 'regular' verb that just needs '-ed' or an 'irregular' verb that changes its spelling. If adding '-ed' sounds strange to your ear, it is likely an irregular verb that requires a special form.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0013","version":2,"contentHash":"sha256:203af0a2f1c4324d72c98277c01ba2ee3a2742e8650658188234653c062b268f","question":"Which is correct: 'The cats ___ sleeping.'","choices":["is","are","was","be"],"correct":1,"explanation":{"correct":"Answer: are. The subject 'cats' is plural, so you must use the plural verb form 'are' to match it. This is a classic example of subject-verb agreement.","incorrect":[{"choice":"is","category":"subject-verb disagreement","reason":"'Is' is a singular verb used for one person or thing. Since 'cats' is plural (more than one), you cannot use 'is'."},"",{"choice":"was","category":"singular past tense","reason":"'Was' is also a singular verb. Even though it describes the past, it does not match the plural subject 'cats'."},{"choice":"be","category":"incorrect verb form","reason":"'Be' is the base form of the verb. It does not function correctly in this sentence structure; you need a form that agrees with the plural subject."}]},"studyAid":{"definition":"A plural subject must always be paired with a plural verb, while a singular subject must be paired with a singular verb.","example":"The dog is barking (singular). The dogs are barking (plural). The cat was sleeping (singular). The cats were sleeping (plural).","strategyClue":"Look at the subject word in the sentence. Decide if it represents one item or multiple items, then select the verb that matches that quantity.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0014","version":2,"contentHash":"sha256:97f6026afcb975a09eae2ea7759869ab8bbdfa02b06102c90f59b6229f10cd6f","question":"What is the past participle of 'break'?","choices":["broke","broken","breaked","breaking"],"correct":1,"explanation":{"correct":"Answer: broken. The past participle of 'break' is an irregular form. Unlike regular verbs that add -ed, 'break' changes its internal vowel to become 'broken' when used after 'have' or 'has'.","incorrect":[{"choice":"broke","category":"past tense error","reason":"'Broke' is the simple past tense (e.g., 'I broke the cup yesterday'), not the past participle. Use the past participle after helping verbs like 'have' or 'had'."},"",{"choice":"breaked","category":"regular verb error","reason":"'Break' is an irregular verb. You cannot add -ed to it. 'Breaked' is not a word in standard English."},{"choice":"breaking","category":"present participle error","reason":"'Breaking' is the present participle or gerund. It describes an action happening now (e.g., 'I am breaking') rather than a completed action."}]},"studyAid":{"definition":"A past participle is the form of a verb used after helping verbs like 'have', 'has', or 'had' to show completed action.","example":"I have eaten (not 'I have ate'). She has broken (not 'She has broke'). We have gone (not 'We have went').","strategyClue":"Test the word by placing 'I have' in front of it. If the phrase sounds like something that happened in the past, you have identified the correct past participle form.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0015","version":3,"contentHash":"sha256:dd4df81756bb00cdcfd151ef4b06af295a0afd7374dc71c804dbb41859dadae8","question":"Which is correct: 'I ___ not want to leave.'","choices":["do","does","did","Both A and C"],"correct":3,"explanation":{"correct":"Answer: Both 'do' and 'did'. Both 'do' and 'did' are correct because they correctly agree with the subject 'I' in either the present or past tense.","incorrect":[{"choice":"do","reason":"\"do\" keeps the verb pattern acceptable, so it is not the verb error the prompt asks you to find."},{"choice":"does","category":"subject-verb agreement","reason":"The verb 'does' is only used with third-person singular subjects like 'he', 'she', or 'it'. Since our subject is 'I', 'does' does not fit."},{"choice":"did","reason":"\"did\" keeps the verb pattern acceptable, so it is not the verb error the prompt asks you to find."},""]},"studyAid":{"definition":"Subject-verb agreement means matching the verb to the subject. Use 'do' or 'did' for 'I', 'you', 'we', and 'they', but use 'does' for 'he', 'she', and 'it'.","example":"I do not know. She does not know. I did not go yesterday.","strategyClue":"Identify the subject of the sentence first. Then, test each verb choice by saying the sentence aloud to see if it follows the standard pattern for 'I'.","link":"https://www.grammar-monster.com/glossary/verbs.htm","linkText":"Grammar Monster - Verbs"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-verb-forms","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0016","version":3,"contentHash":"sha256:6a11247f2b2ee8843683278ace0d6727f7dfcb2bd934220258eb6a84a34bc3e7","question":"Choose the best missing word. Juan ______ the treats for the party.","choices":["brang","brung","bringed","brought"],"correct":3,"explanation":{"correct":"Answer: brought. 'Brought' is the correct irregular past tense form of the verb 'bring.'","incorrect":[{"choice":"brang","category":"irregular verb error","reason":"'Brang' is not a real word in English. Irregular verbs like 'bring' do not follow standard -ed rules or vowel-shifting patterns like 'sang'."},{"choice":"brung","category":"past participle error","reason":"'Brung' is a past participle that usually needs a helping verb like 'had' or 'has.' It cannot stand alone as the main verb of this sentence."},{"choice":"bringed","category":"regular verb error","reason":"You cannot add '-ed' to 'bring' because it is an irregular verb. We must use the memorized form 'brought' instead."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":16,"sourceFile":"Advanced-1_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Some verbs are 'irregular,' which means they don't follow the normal -ed pattern to show past tense. You have to memorize their specific past tense forms.","example":"bring/brought, teach/taught, think/thought, catch/caught","strategyClue":"Try saying the sentence with the word 'yesterday' at the beginning. Listen for which version of the verb sounds natural to your ears when describing something that already happened.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-verb-forms-q0017","version":3,"contentHash":"sha256:9a2051fc815ad496d1669068a6980d5a635a46500393d54e1add058a7d051acf","question":"Choose the correct verb. After Marco finds the solution, he ______ it with the class.","choices":["will share","has shared","shared","share"],"correct":0,"explanation":{"correct":"Answer: will share. This sentence describes an event that will happen in the future, after a specific action is completed. Using 'will' shows the future tense clearly.","incorrect":["",{"choice":"has shared","category":"present perfect tense","reason":"The phrase 'has shared' implies the action is already finished in the past or present, but the sentence describes something that happens after Marco finds the solution."},{"choice":"shared","category":"past tense verb","reason":"The word 'shared' describes an action that already happened. Since Marco finds the solution first, the action with the class happens later."},{"choice":"share","category":"subject-verb disagreement","reason":"Using 'he share' is incorrect because the subject 'he' is singular. It would need to be 'shares' for the present tense, but that doesn't fit the future timing of the sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":17,"sourceFile":"Advanced-2_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Future tense verbs describe actions that have not happened yet. We often use the word 'will' followed by the base verb to talk about the future.","example":"He will run later. She will eat lunch. They will play soccer.","strategyClue":"Look at the timing of the sentence. If the action happens after another task is finished, identify which option describes an action yet to come.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0018","version":2,"contentHash":"sha256:6797fb954cffca3bfa099da7842c9c144542c57067189c6a1603541406adbcfe","question":"Choose the best missing irregular verb. I ______________ on the beach for three hours.","choices":["laid","have lain","have laid","have been laying"],"correct":1,"explanation":{"correct":"Answer: have lain. 'Lain' is the correct past participle of the intransitive verb 'lie,' which means to rest or recline. Because the subject is resting rather than placing an object down, the verb 'lie' is required.","incorrect":[{"choice":"laid","category":"wrong verb form","reason":"'Laid' is the past tense of 'lay,' which means to put something down. Since you are talking about resting yourself on the beach, you need a form of 'lie' instead."},"",{"choice":"have laid","category":"transitive vs intransitive","reason":"'Have laid' implies that you placed an object somewhere else. It is not the correct choice for describing your own resting state."},{"choice":"have been laying","category":"incorrect verb usage","reason":"'Laying' is a form of 'lay,' meaning to put something down. Even in a continuous form, it requires an object to receive the action, which isn't present in this sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":18,"sourceFile":"Advanced-2_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The verb 'lie' (to rest) uses 'lain' as its past participle, while the verb 'lay' (to place an object) uses 'laid' as its past participle.","example":"I lie down every day. I lay the book down yesterday. I have lain here for hours. I have laid the book on the table.","strategyClue":"Ask yourself: 'Am I resting, or am I putting something down?' If you are resting, look for the 'lie' family of words; if you are placing an object, look for the 'lay' family.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0019","version":4,"contentHash":"sha256:687b6819ff1c6583b570ad432135b6242ed77829ab5c080f7643a24ccaf18047","question":"Choose the correct verb. Hasn’t Susie _______ at least an inch this summer.","choices":["grew","been growing","grown","grow"],"correct":2,"explanation":{"correct":"Answer: grown. This sentence uses the present perfect tense with the auxiliary verb 'hasn't,' which requires the past participle form of the verb. The past participle of 'grow' is 'grown'.","incorrect":[{"choice":"grew","category":"simple past error","reason":"'Grew' is the simple past tense. It cannot be used after the auxiliary verb 'hasn't' because the past participle 'grown' is required here."},{"choice":"been growing","category":"tense consistency error","reason":"While 'been growing' is a valid verb phrase, it changes the meaning to an ongoing action rather than a completed state of height change; in this specific context, 'grown' is the standard past participle to show the result of the summer's growth."},"",{"choice":"grow","category":"base form error","reason":"'Grow' is the present base form. It does not fit after 'hasn't,' which needs the past participle to show that the action relates to the time leading up to now."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":19,"sourceFile":"Advanced-5_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The present perfect tense uses 'has' or 'have' plus the past participle of a verb to describe actions that happened in the past and continue into or affect the present.","example":"He has grown (correct) vs. He has grew (incorrect); She has eaten (correct) vs. She has ate (incorrect).","strategyClue":"Look at the verb that comes before the blank. If you see 'has' or 'have,' test the verb by asking yourself, 'Which form of the word sounds correct after the word has?'","link":"","linkText":""}},{"id":"grammar-verb-forms-q0020","version":2,"contentHash":"sha256:a4ee2e5e2fe41e32c38b623b1f3db3ad45e57fde5a20ed50afa6027b4e9196f8","question":"Which one of the sentences is written in past tense?","choices":["The students must read chapter 2 for homework.","I have been reading a novel a week.","I read the endof the novel last night.","Greg seems to be making progress."],"correct":2,"explanation":{"correct":"Answer: I read the end of the novel last night. The word 'read' is the past tense form here, and the phrase 'last night' signals that the action is already finished.","incorrect":[{"choice":"The students must read chapter 2 for homework.","category":"modal verb usage","reason":"This sentence uses the modal 'must', which indicates a current obligation or a future requirement, not an action that has already happened."},{"choice":"I have been reading a novel a week.","category":"present perfect continuous","reason":"This sentence uses 'have been reading,' which describes an action that started in the past and is still continuing in the present."},"",{"choice":"Greg seems to be making progress.","category":"present tense verb","reason":"The verb 'seems' is in the present tense, describing what is happening right now, rather than an event that took place in the past."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":20,"sourceFile":"Advanced-5_grammer and usage.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Past tense verbs describe actions that have already happened. Many past tense verbs end in -ed, but some are irregular and change their spelling.","example":"Present: I walk. Past: I walked. Present: I buy. Past: I bought.","strategyClue":"Look for time indicator words like 'yesterday', 'last night', or 'ago' that signal the past, and check if the verb form shows the action is completed.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0021","version":3,"contentHash":"sha256:1d78573d1eb686a3c3ff19754c172ed8b3e615ecc17a1646cd92b582587ce061","question":"Choose the sentence that contains an error in verb tense.","choices":["Rob erto turns on the television and watched a baseball game.","Sasha read all the directions then completed the assignment.","Eduardo finishes his paper route before he goes to school.","Great literature, which stirs the imagin ation, also challenges the intellect."],"correct":0,"explanation":{"correct":"Answer: Roberto turns on the television and watched a baseball game. The verbs 'turns' (present tense) and 'watched' (past tense) do not match. Since they are part of the same action sequence, they should both be in the same tense.","incorrect":["",{"choice":"Sasha read all the directions then completed the assignment.","category":"consistent verb tense","reason":"The verbs 'read' and 'completed' are both in the past tense. Because they both describe actions that already finished, this sentence is correct."},{"choice":"Eduardo finishes his paper route before he goes to school.","category":"consistent verb tense","reason":"Both 'finishes' and 'goes' are present tense verbs. This shows the actions happen regularly in the present, so the sentence is grammatically correct."},{"choice":"Great literature, which stirs the imagin ation, also challenges the intellect.","category":"consistent verb tense","reason":"The verbs 'stirs' and 'challenges' are both in the present tense. Using the same tense for both actions keeps the sentence flowing smoothly."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":21,"sourceFile":"Advanced-6_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"When a sentence contains multiple verbs about the same event or subject, they should stay in the same tense (past, present, or future) unless the timing of the action clearly changes.","example":"Incorrect: He ran home and eats dinner. Correct: He ran home and ate dinner. Correct: He runs home and eats dinner.","strategyClue":"Identify all the main verbs in the sentence. Check if they all share the same time frame by looking for markers like '-ed' at the end of words or common present tense endings like '-s'.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0022","version":3,"contentHash":"sha256:86d86ef10b0ae12802a1be73c498f3a2752299b4b630d2b9dc7518619ad4f5b9","question":"Which sentence is NOT correct?","choices":["Harry sat in his assigned seat.","The meeting came to a close.","The rain bringed moisture to the flo wers.","The plane flew over the mountain."],"correct":2,"explanation":{"correct":"Answer: The rain bringed moisture to the flowers. The word 'bringed' is incorrect because 'bring' is an irregular verb. Its past tense form is 'brought', not 'bringed'.","incorrect":[{"choice":"Harry sat in his assigned seat.","category":"correct past tense","reason":"The verb 'sat' is the correct past tense form of 'sit'. This sentence is grammatically correct."},{"choice":"The meeting came to a close.","category":"correct past tense","reason":"The verb 'came' is the correct past tense form of 'come'. This sentence is grammatically correct."},"",{"choice":"The plane flew over the mountain.","category":"correct past tense","reason":"The verb 'flew' is the correct past tense form of 'fly'. This sentence is grammatically correct."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":22,"sourceFile":"Basic-2_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Regular verbs add '-ed' to show past tense, but irregular verbs change their spelling in special ways.","example":"Bring -> brought (not bringed), Sit -> sat (not sitted), Fly -> flew (not flyed)","strategyClue":"Identify the action word in each sentence and test if it sounds right when you add '-ed' to it; if the word sounds strange or incorrect, check if it is an irregular verb that has its own special past tense form.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0023","version":2,"contentHash":"sha256:795aac4138f891c8f4e0d1d47283148b6ea737b5fa603768182fc7943955853c","question":"Which sentence is written in present tense?","choices":["Henry ran the race.","Lisa swims on the swim team.","Ruth will help with the lesson.","Troy could have eaten the last cookie."],"correct":1,"explanation":{"correct":"Answer: Lisa swims on the swim team. The verb 'swims' indicates an action that is currently happening or happens regularly, which is the definition of simple present tense.","incorrect":[{"choice":"Henry ran the race.","category":"past tense verb","reason":"The word 'ran' is the past tense of 'run', which shows the action is finished. This sentence describes something that happened in the past, not now."},"",{"choice":"Ruth will help with the lesson.","category":"future tense verb","reason":"The word 'will' indicates future tense. This shows that the action has not started yet and will happen later."},{"choice":"Troy could have eaten the last cookie.","category":"modal perfect tense","reason":"The phrase 'could have eaten' shows a possibility about the past. It does not describe an action happening in the present moment."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":23,"sourceFile":"Basic-3_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Simple present tense describes actions that are happening right now or actions that happen regularly, like habits or truths.","example":"I eat lunch. (present) / I ate lunch. (past) / I will eat lunch. (future)","strategyClue":"Look at the main action verb in each sentence and ask yourself: 'Did this already happen, is it going to happen, or is it happening as part of a regular routine right now?'","link":"","linkText":""}},{"id":"grammar-verb-forms-q0024","version":2,"contentHash":"sha256:e0be1ee445c0c8b71beadb209ef1632fe73a1947c753ec2524011c989636ff23","question":"Which verb correctly completes the sentence? The bus driver had _______ the same bus the day before.","choices":["d riven","drives","drive","driving"],"correct":0,"explanation":{"correct":"Answer: driven. The sentence uses the helping verb 'had', which indicates the past perfect tense. The past participle of 'drive' is 'driven'.","incorrect":["",{"choice":"drives","category":"present tense verb","reason":"This is the present tense form. It does not fit with 'had', which signals that the action happened in the past."},{"choice":"drive","category":"base verb form","reason":"The base form 'drive' is used for simple present tense or after certain helping verbs, but it cannot follow 'had' in this sentence."},{"choice":"driving","category":"present participle","reason":"The present participle 'driving' would require a form of 'be' (like 'was' or 'were') to work. It does not follow 'had' correctly."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":24,"sourceFile":"Basic-5_grammer and usage.pdf","sourceQuestionNumber":7,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The past perfect tense is formed by using 'had' plus the past participle of a verb. Irregular verbs often change their form significantly in the past participle.","example":"I had seen the movie. She had written the letter. We had eaten lunch.","strategyClue":"Look at the word before the blank. If you see 'had', try adding the '-en' or '-n' version of the verb, as many past participles end with those letters.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0025","version":3,"contentHash":"sha256:c5b0cafc252f63e0cef2ae65dc4b06c01584d660f3a287172b94159282b6430d","question":"Choose the correct verb to complete the sentence. The wind ______ the leaves off the tree.","choices":["b lown","blow","have blew","blew"],"correct":3,"explanation":{"correct":"Answer: blew. The verb 'blew' is the correct past tense form of the irregular verb 'blow'. Since the sentence describes an action that happened in the past, we use the simple past tense.","incorrect":[{"choice":"b lown","category":"incorrect spelling","reason":"This is a spelling error. The word 'blown' is the past participle used with helping verbs like 'has' or 'had', and it does not contain a space in the middle."},{"choice":"blow","category":"present tense usage","reason":"The word 'blow' is present tense. If you use it here, it implies the wind does this every day, but the sentence structure suggests a completed action in the past."},{"choice":"have blew","category":"helping verb error","reason":"You cannot pair 'have' with the simple past 'blew'. If you need a helping verb, you must use the past participle 'blown' (e.g., 'The wind has blown')."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":25,"sourceFile":"Basic-6_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Irregular verbs change their spelling when moving from present to past tense instead of just adding '-ed'. You must memorize these special forms.","example":"Present: blow, Past: blew; Present: grow, Past: grew; Present: throw, Past: threw","strategyClue":"Ask yourself if the action is happening right now or if it already finished. If the action is finished, look for the specific past tense word form that does not need a helper like 'have'.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0026","version":2,"contentHash":"sha256:b45af38bc7bf10add83624cde3e0a37c685b7f44ad53af27d2a4069cee96fd3e","question":"Which verb belongs in the blank? I ______________ rolls to last night’s awards banquet.","choices":["brang","bringed","brought","will bring"],"correct":2,"explanation":{"correct":"Answer: brought. The verb 'bring' is an irregular verb. Its past tense form is 'brought', not 'brang' or 'bringed'.","incorrect":[{"choice":"brang","category":"irregular verb error","reason":"Although this sounds like the past tense of 'ring' (rang), 'brang' is not a real word. The past tense of 'bring' is 'brought'."},{"choice":"bringed","category":"overregularization error","reason":"We usually add '-ed' to make verbs past tense, but 'bring' is irregular. 'Bringed' is incorrect; use the special form 'brought' instead."},"",{"choice":"will bring","category":"wrong verb tense","reason":"The sentence specifies 'last night's awards banquet,' which happened in the past. 'Will bring' refers to the future, so it does not fit the timeline."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":26,"sourceFile":"Basic-6_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Irregular verbs do not follow the standard rule of adding '-ed' to show past tense; they change their spelling entirely.","example":"bring/brought, buy/bought, teach/taught, think/thought","strategyClue":"Identify the time clue in the sentence first. If the action happened in the past, search for the irregular past tense form instead of just adding letters to the base verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0027","version":3,"contentHash":"sha256:f9f0da926ab7a51d99cbc5088bb1b527eb3aaf4fcf975806dd95a72bcc3ee893","question":"Choose the correct verb to complete the sentence. The class fin ally ___________ to understand the math problem.","choices":["begin","has began","began","be gun"],"correct":2,"explanation":{"correct":"Answer: began. This sentence describes an event that already happened in the past, so we must use the simple past tense form of the verb 'begin', which is 'began'.","incorrect":[{"choice":"begin","category":"wrong verb tense","reason":"'Begin' is the present tense form. Because the sentence describes a completed action, we need the past tense 'began'."},{"choice":"has began","category":"incorrect verb form","reason":"The phrase 'has began' is grammatically incorrect. When using 'has' as a helping verb, you must use the past participle form 'begun' (has begun)."},"",{"choice":"be gun","category":"spelling error","reason":"'Be gun' is not a verb; it is a misspelling of the word 'begun'. Even if spelled correctly, 'be gun' does not fit the sentence structure."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":27,"sourceFile":"Basic-7_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The simple past tense is used for actions that finished at a specific time in the past. Irregular verbs like 'begin' change their spelling in the past tense instead of just adding '-ed'.","example":"Present: I begin my work. Past: I began my work yesterday. Present: She begins to run. Past: She began to run.","strategyClue":"Look at the sentence to see if it is describing something happening right now or something that finished in the past. If the action is finished, choose the form that shows past time.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0028","version":2,"contentHash":"sha256:f0ee0362906aef185e3bf0fff4fddc4de7db2c43e0ca9108939c0a6abdc0b40d","question":"What is the past tense verb of eat.","choices":["eat en","eated","ated","ate"],"correct":3,"explanation":{"correct":"Answer: ate. The verb 'eat' is an irregular verb, which means it does not follow the standard rule of adding '-ed' to show the past tense.","incorrect":[{"choice":"eat en","category":"past participle error","reason":"'Eaten' is the past participle used with helper verbs like 'have' or 'had' (e.g., 'I have eaten'). It cannot stand alone as the simple past tense."},{"choice":"eated","category":"incorrect verb conjugation","reason":"'Eated' is not a word in English. Because 'eat' is an irregular verb, it does not form the past tense by simply adding '-ed'."},{"choice":"ated","category":"incorrect spelling/form","reason":"'Ated' is not a recognized form of the verb 'eat'. The correct irregular past tense form is 'ate'."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":28,"sourceFile":"Proficient-1_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Regular verbs form the past tense by adding '-ed', but irregular verbs change their spelling entirely to show past action.","example":"jump -> jumped (regular); eat -> ate (irregular); run -> ran (irregular)","strategyClue":"Think about how you would say the sentence if it happened yesterday. If the verb sounds unusual when you add '-ed', it is likely an irregular verb that has a unique past tense spelling.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0029","version":2,"contentHash":"sha256:e6ccada26fc5278d4552419ebda88a51f38671d28df9507f8c0a8fa9363726d3","question":"When does the action take place? The geese will fly south for the winter","choices":["p resent","past","past perfect","future"],"correct":3,"explanation":{"correct":"Answer: future. The phrase 'will fly' uses the helping verb 'will' to show that the action is planned to happen at a later time, which indicates the future tense.","incorrect":[{"choice":"p resent","category":"present tense error","reason":"The present tense would describe an action happening right now, such as 'The geese fly south.' Since the sentence uses 'will,' it is not happening in the present."},{"choice":"past","category":"past tense error","reason":"The past tense describes actions that already finished. 'Will fly' does not describe something that happened yesterday or in the past."},{"choice":"past perfect","category":"verb tense error","reason":"The past perfect tense would use 'had flown' to describe an action completed before another past action. This sentence does not involve a past time frame."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":29,"sourceFile":"Proficient-1_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Future tense describes actions that have not happened yet but will happen later. We often use the helping verb 'will' before the main verb to show this.","example":"Future: I will eat dinner. Past: I ate dinner. Present: I eat dinner.","strategyClue":"Look at the verb phrase in the sentence. Ask yourself if the action is currently happening, already finished, or if it is a promise or plan for later.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0030","version":2,"contentHash":"sha256:6bfef21b6826d1dcebdf56144c8959782a84fd25cf19ddf8e9ffc1817ca90683","question":"Dad passed the bowl of mashed potatoes to his aunt. When does the action take place?","choices":["p ast","present","present perfect","future"],"correct":0,"explanation":{"correct":"Answer: past. The verb 'passed' ends in -ed, which shows that the action has already happened and is finished.","incorrect":["",{"choice":"present","category":"verb tense error","reason":"The word 'present' describes actions happening right now. Since the verb is 'passed', the action is not occurring at this moment."},{"choice":"present perfect","category":"tense structure error","reason":"The 'present perfect' tense uses 'has' or 'have' (e.g., 'has passed'). Because this sentence only uses the single verb 'passed', it is simple past."},{"choice":"future","category":"verb tense error","reason":"The future tense describes actions that haven't happened yet, usually using 'will'. 'Passed' refers to an action that is already complete."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":30,"sourceFile":"Proficient-2_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The simple past tense is used to describe actions that started and finished in the past. Most past tense verbs end in -ed.","example":"I walked (past) vs. I walk (present); She jumped (past) vs. She jumps (present).","strategyClue":"Look at the ending of the action word in the sentence. If you see an -ed ending, ask yourself if that action is something that happened before now.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0031","version":3,"contentHash":"sha256:0826ce5f064e6458c0fb4ff757556369772ca359f5edfa4af1b688d9bb582920","question":"Which sentence below does NOT have an irregular verb in it?","choices":["Unfortunately, the wind blew down the newly planted trees.","In Egypt, there are pyramids in which treasures lie.","Joe returned home after three years in the army.","Amanda threw the baseball over the fence just o anger Tim."],"correct":2,"explanation":{"correct":"Answer: Joe returned home after three years in the army. The verb 'returned' is a regular verb because it follows the standard pattern of adding '-ed' to the base form to show past tense.","incorrect":[{"choice":"Unfortunately, the wind blew down the newly planted trees.","category":"irregular past tense","reason":"The verb 'blew' is irregular because it does not end in '-ed' for the past tense. Its base form is 'blow'."},{"choice":"In Egypt, there are pyramids in which treasures lie.","category":"irregular verb form","reason":"The verb 'lie' is an irregular verb. Regular verbs follow predictable rules, but 'lie' changes in unique ways when used in different tenses (like 'lay' or 'lain')."},"",{"choice":"Amanda threw the baseball over the fence just o anger Tim.","reason":"\"Amanda threw the baseball over the fence just o anger Tim.\" keeps the verb pattern acceptable, so it is not the verb error the prompt asks you to find."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":31,"sourceFile":"Proficient-2_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A regular verb follows a predictable pattern by adding '-ed' to the end to form the past tense. Irregular verbs do not follow this pattern and change their spelling or sound in unique ways.","example":"Regular: play/played, walk/walked. Irregular: eat/ate, swim/swam, run/ran.","strategyClue":"Look at the main verb in each sentence and ask yourself: 'Does this word end in -ed to show past tense?' If the answer is no, it is likely an irregular verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0032","version":2,"contentHash":"sha256:f89a0e43e7c6e48cc0249ab1f8648958b8db109b4389f791d0f3a3e13435a671","question":"Choose the wordor words that mean the action will happen in the future. Julio _______ many soccer plays when he goes to soccer camp next week.","choices":["learns","will learn","learned","has learned"],"correct":1,"explanation":{"correct":"Answer: will learn. The phrase 'next week' indicates that the action has not happened yet, so we use the future tense 'will learn' to show it is planned for the future.","incorrect":[{"choice":"learns","category":"present tense error","reason":"The word 'learns' describes something that happens regularly or right now. Since the sentence says 'next week,' this choice does not fit."},"",{"choice":"learned","category":"past tense error","reason":"The word 'learned' describes an action that is already finished. Because the event is taking place 'next week,' the past tense is incorrect."},{"choice":"has learned","category":"present perfect error","reason":"'Has learned' suggests the learning is already complete up to this point in time. This contradicts the future timeframe of 'next week.'"}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":32,"sourceFile":"Proficient-2_grammer and usage.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Future tense describes actions that have not happened yet. We typically form it by adding the helping verb 'will' before the action word.","example":"I will go, he will run, she will play.","strategyClue":"Look for time-related clues in the sentence like 'next week,' 'tomorrow,' or 'soon.' These words are signs that you should choose an option containing the word 'will.'","link":"","linkText":""}},{"id":"grammar-verb-forms-q0033","version":2,"contentHash":"sha256:aa36566e6cf383e094e06533c47c6ff59483e4ef821be26ed0950b912b8c9133","question":"If you wanted to tell about something that has already happened, you would use a:","choices":["Fu ture tense verb","Past tense verb","Present tense verb","Future perfect verb"],"correct":1,"explanation":{"correct":"Answer: Past tense verb. Verbs in the past tense describe actions or states that have already finished or taken place in the past.","incorrect":[{"choice":"Fu ture tense verb","category":"future time reference","reason":"Future tense verbs describe things that haven't happened yet, so they are not appropriate for actions that have already occurred."},"",{"choice":"Present tense verb","category":"current time reference","reason":"Present tense verbs tell us about what is happening right now or what happens regularly, not about events already completed."},{"choice":"Future perfect verb","category":"complex tense error","reason":"Future perfect verbs describe an action that will be completed at a specific time in the future, which is the opposite of the past."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":33,"sourceFile":"Proficient-3_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Past tense verbs show that an action is finished. Most past tense verbs are made by adding '-ed' to the end of the word.","example":"jump -> jumped (past), play -> played (past), walk -> walked (past)","strategyClue":"Ask yourself: 'Is the action happening right now, or is it already over?' If the event is finished, choose the verb form used to show completed time.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0034","version":2,"contentHash":"sha256:e147fefa4ed50bcebdc619735c6bd25df3f68974ea7e625ea52d2dc40254ff30","question":"Which is the past tense form of the word speak? Gerry speak kindly of his father.","choices":["speaks","will speak","spoke","speaked"],"correct":2,"explanation":{"correct":"Answer: spoke. The verb 'speak' is an irregular verb, which means it does not follow the regular -ed pattern to form the past tense. 'Spoke' is the correct past tense form.","incorrect":[{"choice":"speaks","category":"present tense verb","reason":"'Speaks' is the present tense form. It describes an action happening now, not an action that already happened in the past."},{"choice":"will speak","category":"future tense verb","reason":"'Will speak' is the future tense. It describes an action that has not happened yet, rather than one that is finished."},"",{"choice":"speaked","category":"incorrect verb conjugation","reason":"Although many verbs end in -ed for the past tense, 'speak' is an irregular verb. 'Speaked' is not a word in standard English."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":34,"sourceFile":"Proficient-4_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Irregular verbs are verbs that change their spelling in the past tense instead of simply adding -ed.","example":"speak -> spoke, eat -> ate, run -> ran","strategyClue":"Ask yourself if the sentence happened in the past, then determine if the verb is a 'regular' verb that takes -ed or an 'irregular' verb that changes its spelling entirely.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0035","version":3,"contentHash":"sha256:f0b17d7ee71c656a608f1a07ad8b79431812cd62484d86b07f9a0bfedc6dca70","question":"Choose the correct verb. Yesterday, Jason and Ellen ________ to school together.","choices":["w alk","walked","walks","walking"],"correct":1,"explanation":{"correct":"Answer: walked. The word 'Yesterday' indicates that the action happened in the past. To show past tense for a regular verb like 'walk', we add '-ed' to the end.","incorrect":[{"choice":"w alk","category":"spelling error","reason":"This choice has an accidental space in the middle of the word, making it not a real English verb."},"",{"choice":"walks","category":"present tense verb","reason":"The '-s' ending is used for present tense actions, but 'Yesterday' tells us the action is already finished."},{"choice":"walking","category":"incorrect verb form","reason":"The '-ing' form needs a helping verb like 'were' to make sense; it cannot stand alone as the main verb of this sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":35,"sourceFile":"Proficient-4_grammer and usage.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Past tense verbs show actions that already happened. For most verbs, you show this by adding '-ed' to the end of the word.","example":"Correct: I played outside yesterday. Incorrect: I play outside yesterday.","strategyClue":"Look for words like 'yesterday', 'last week', or 'ago' in the sentence. These time words are your clues that you must choose the verb form ending in '-ed'.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0036","version":3,"contentHash":"sha256:1f91164c5d6b87d69aff3616c08f5ed64db720cc1cd060bf33427c1fb7bf31c3","question":"Choose the best missing word. Three weeks ago, my dog _______ away.","choices":["ran","runs","has run","has ran"],"correct":0,"explanation":{"correct":"Answer: ran. Because the sentence says 'Three weeks ago,' it describes an action that finished in the past. Therefore, we must use the simple past tense form of the verb 'run,' which is 'ran.'","incorrect":["",{"choice":"runs","category":"present tense error","reason":"The word 'runs' is present tense, used for things happening right now. Since the sentence says 'Three weeks ago,' we need a past tense verb."},{"choice":"has run","category":"present perfect tense","reason":"'Has run' is used for actions that happened at an unspecified time or started in the past and continue to now. It does not fit with a specific time marker like 'three weeks ago.'"},{"choice":"has ran","category":"incorrect verb form","reason":"The word 'ran' is the simple past tense, and 'run' is the past participle. We never use 'has' with the simple past form 'ran.' It should either be 'ran' or 'has run.'"}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":36,"sourceFile":"Proficient-5_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The simple past tense is used to describe an action that started and finished in the past. Many verbs have a special past tense form that you use instead of the present tense.","example":"Present: I run every day. Past: I ran yesterday. Present: She eats lunch. Past: She ate lunch.","strategyClue":"Identify the time clue in the sentence. If the sentence points to a specific finished time in the past, choose the single-word past tense verb form.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-verb-forms-q0037","version":2,"contentHash":"sha256:bd8c4bb89b826ae21cd503e806fed16d66eb390eaafa573e439dd0a96d368374","question":"Identify the cluster of verbs in the present tense.","choices":["b ring, eat, fly","knew, drew, flew","dragged, ate, gave","blown, begun, chosen"],"correct":0,"explanation":{"correct":"Answer: bring, eat, fly. These three verbs are in the present tense, meaning they describe actions happening right now.","incorrect":["",{"choice":"knew, drew, flew","category":"past tense verbs","reason":"These verbs are all in the past tense. They describe actions that have already finished, rather than actions happening now."},{"choice":"dragged, ate, gave","category":"irregular past tense","reason":"These verbs are in the past tense. Even though they don't all end in -ed, they still describe events that happened previously."},{"choice":"blown, begun, chosen","category":"past participle forms","reason":"These are past participles, which are usually used with helping verbs like 'has' or 'have.' They cannot stand alone as simple present tense verbs."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":37,"sourceFile":"Proficient-5_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Present tense verbs describe actions that are happening right now or occur regularly.","example":"Present: I walk, she eats. Past: I walked, she ate.","strategyClue":"Test each verb by putting the word 'today' in front of it. If the sentence makes sense, the verb is likely in the present tense.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0038","version":3,"contentHash":"sha256:9b207af7011fef28fd0cd9aef62f9ecf04279bec9272aa111f9076e55816f276","question":"Choose the correct verb phrase. She ______________ to see the doctor for hours.","choices":["h ave been waiting","has been waited","has been waiting","have been waited"],"correct":2,"explanation":{"correct":"Answer: has been waiting. This sentence uses the present perfect continuous tense to describe an action that started in the past and is still happening, or just finished. 'She' is a third-person singular pronoun, so it requires the verb form 'has' rather than 'have'.","incorrect":[{"choice":"h ave been waiting","category":"subject-verb disagreement","reason":"The pronoun 'She' is singular, so you must use 'has' instead of 'have'. 'Have' is only used for plural subjects or 'I' and 'you'."},{"choice":"has been waited","category":"incorrect verb form","reason":"The phrase 'has been waited' implies that someone else is waiting for her. Since she is the one doing the waiting, you must use the present participle 'waiting'."},"",{"choice":"have been waited","category":"subject-verb and form","reason":"This choice contains two errors: 'have' does not match the singular subject 'she', and 'waited' incorrectly describes the action she is currently doing."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":38,"sourceFile":"Proficient-7_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The present perfect continuous tense is formed by using 'has/have been' + the verb ending in '-ing'. It shows an action that started in the past and continues to the present.","example":"Correct: He has been running. Incorrect: He have been running. Correct: She has been sleeping. Incorrect: She has been slept.","strategyClue":"First, identify the subject to see if it needs 'has' or 'have'. Then, check if the action is something the person is doing themselves; if so, use the '-ing' ending.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0039","version":3,"contentHash":"sha256:88abe320eadce351f613efb5cc5cfc2a8aa2e0e74f8d78079a0f3e01e0bae75f","question":"Choose the best missing word. Paula has _______ for 24 hours straight.","choices":["d riven","drived","drive","drove"],"correct":0,"explanation":{"correct":"Answer: driven. The verb 'drive' is irregular. When using the helping verb 'has', you must use the past participle form, which is 'driven'.","incorrect":["",{"choice":"drived","category":"incorrect verb conjugation","reason":"'Drived' is not a word in English. Irregular verbs do not follow the standard '-ed' pattern in their past participle form."},{"choice":"drive","category":"incorrect verb tense","reason":"The base form 'drive' cannot follow 'has' to describe an action that started in the past and continues or has just finished."},{"choice":"drove","category":"simple past error","reason":"'Drove' is the simple past tense, but it cannot be used with the auxiliary verb 'has'. Use 'has' with the past participle 'driven' instead."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":39,"sourceFile":"Proficient-7_grammer and usage.pdf","sourceQuestionNumber":7,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"The past participle is the form of the verb used with helping verbs like 'has', 'have', or 'had'. Irregular verbs often change their spelling in the past participle.","example":"He has driven (not drove), She has eaten (not ate), We have seen (not saw).","strategyClue":"Ask yourself if the verb is regular or irregular. If it is irregular, try saying the sentence with 'has' plus each option to see which one sounds natural in the past participle form.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-verb-forms-q0040","version":2,"contentHash":"sha256:3caa5ed682c30664ff5b60914ae00d3f4448453d192b0f97ef60c08b519335ac","question":"Read the sentence below. The leaves have ________ to fall from the maple trees. Which word correctly completes the sentence?","choices":["beginning","begun","begin","began"],"correct":1,"explanation":{"correct":"Answer: begun. Because the sentence uses the helping verb 'have', we must use the past participle form of the verb. 'Begun' is the correct past participle for the verb 'begin'.","incorrect":[{"choice":"beginning","category":"incorrect verb tense","reason":"Using 'beginning' with 'have' makes the sentence incomplete; it implies an action currently happening without a supporting verb structure."},"",{"choice":"begin","category":"base verb form","reason":"The base form 'begin' does not work with 'have'. When we use 'have', 'has', or 'had', we need the past participle 'begun' instead."},{"choice":"began","category":"simple past confusion","reason":"'Began' is the simple past tense, used without a helping verb. We cannot use 'have began' because the past participle 'begun' is required after 'have'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":40,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":43,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The verb 'begin' changes forms based on tense: the present is 'begin', the simple past is 'began', and the past participle (used after helping verbs like 'have' or 'had') is 'begun'.","example":"I begin today. I began yesterday. I have begun already.","strategyClue":"Look at the word immediately before the blank. If you see 'have', 'has', or 'had', your brain should look for the 'past participle' version of the verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0041","version":2,"contentHash":"sha256:6a167d3bf933bb3de81ac12bd96f91a8da3f756b907565db91a3e596d6cfadee","question":"Identify the verb tense used in the sentence. Shelly will have eaten all of the brownies by evening.","choices":["past tense","future tense","future perfect tense","past perfect tense"],"correct":2,"explanation":{"correct":"Answer: future perfect tense. This tense uses 'will have' followed by the past participle 'eaten' to describe an action that will be finished at a specific time in the future.","incorrect":[{"choice":"past tense","category":"incorrect verb time","reason":"Past tense describes actions that already happened. Since the sentence uses 'will,' it is looking forward to the future, not back at the past."},{"choice":"future tense","category":"insufficient tense description","reason":"While the sentence is in the future, 'future tense' usually refers only to 'will eat.' Because this sentence includes 'have' to show completion, it is more specifically future perfect."},"",{"choice":"past perfect tense","category":"incorrect time reference","reason":"Past perfect uses 'had' instead of 'will have' to show an action finished before another point in the past. Here, the action is set in the future."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":41,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":49,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The future perfect tense describes an action that will be completed by a certain time in the future.","example":"Future Perfect: I will have finished my homework by 8:00. Simple Future: I will finish my homework.","strategyClue":"Look for the helper words 'will have' combined with the past participle form of the main verb (e.g., eaten, finished, gone). If you see this pattern, you are looking at a future perfect action.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0042","version":2,"contentHash":"sha256:5e70f42340ebfcad869524dbd9322a5e3417eec584a2be757678568690ddd933","question":"Which sentence is in the irregular past tense?","choices":["Mason washed the dishes before bed.","After midnight, the dogs started howling.","The cow kicked the bucketover in the barn.","The bats flew over our farm every evening."],"correct":3,"explanation":{"correct":"Answer: The bats flew over our farm every evening. 'Flew' is the irregular past tense of the verb 'fly', meaning it does not follow the standard rule of adding -ed to the base word.","incorrect":[{"choice":"Mason washed the dishes before bed.","category":"regular past tense","reason":"The verb 'washed' is formed by adding -ed to 'wash'. This is a regular verb, not an irregular one."},{"choice":"After midnight, the dogs started howling.","category":"regular past tense","reason":"The word 'started' uses the -ed ending to show the past tense, which makes it a regular verb, not irregular."},{"choice":"The cow kicked the bucketover in the barn.","category":"regular past tense","reason":"The word 'kicked' follows the standard rule of adding -ed to the base word 'kick', identifying it as a regular verb."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":42,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":7,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Regular verbs form the past tense by adding -ed, while irregular verbs change their spelling entirely or stay the same.","example":"Regular: play/played, talk/talked. Irregular: fly/flew, eat/ate, go/went.","strategyClue":"Look at the main action word in each sentence and ask yourself: 'Does this word end in -ed?' If it does, it follows the regular rule. If the word changes its spelling completely, it is likely irregular.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0043","version":2,"contentHash":"sha256:f26d8990a47023ce8b36ab6d1910cb7723c74fc8d1004f421ad6c6f0107cc00b","question":"Which sentence shows that Brenda was afraid to fly?","choices":["The airplane ride was bumpy when they flew into a thunderstorm.","Brenda had never flown before and didn’t know what to expect.","The airline steward took Brenda to her seat next to the window.","Brenda’s hand shook as she held her friend’s hand during takeoff."],"correct":3,"explanation":{"correct":"Answer: Brenda’s hand shook as she held her friend’s hand during takeoff. A physical action like shaking hands is a common way to show feelings of nervousness or fear during a scary event like a flight takeoff.","incorrect":[{"choice":"The airplane ride was bumpy when they flew into a thunderstorm.","category":"describing external events","reason":"This sentence describes the weather, not how Brenda felt. While a storm can be scary, the sentence doesn't show Brenda's personal reaction."},{"choice":"Brenda had never flown before and didn’t know what to expect.","category":"stating prior knowledge","reason":"This explains Brenda's experience level, but it doesn't explicitly describe an emotion like fear or nervousness."},{"choice":"The airline steward took Brenda to her seat next to the window.","category":"neutral factual action","reason":"This describes a normal part of boarding an airplane. It does not provide any clues about Brenda's feelings or emotions."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":43,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":35,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To 'show, not tell' means using descriptive physical actions or reactions to let the reader know how a character feels without using emotion words.","example":"Showing fear: Her teeth chattered. Telling fear: She was scared.","strategyClue":"Look for the sentence that focuses on a character's physical body reaction rather than just describing the setting or explaining the situation.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0044","version":2,"contentHash":"sha256:8000c71a7b9b091d2d9f527c4f9c99320e47f65eafcfff0b87053621455e78a8","question":"Which word correctly completes the sentence? Yesterday, Helen ________ doing all she could to finish the science project.","choices":["is","can","was","will"],"correct":2,"explanation":{"correct":"Answer: was. Because the sentence begins with 'Yesterday', we must use the past tense form of the verb. 'Was' is the correct singular past tense verb to match the subject 'Helen'.","incorrect":[{"choice":"is","category":"present tense verb","reason":"'Is' describes something happening now. Since the sentence starts with 'Yesterday', we need a past tense verb instead."},{"choice":"can","category":"modal verb misuse","reason":"'Can' is a helping verb that describes ability in the present. It does not fit the past time context established by the word 'Yesterday'."},"",{"choice":"will","category":"future tense verb","reason":"'Will' refers to future events. Since the action happened yesterday, 'will' is incorrect because it points to the future rather than the past."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":44,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Verbs must match the time period of the sentence. Use past tense verbs to describe actions that have already finished.","example":"Today he is happy (present). Yesterday he was happy (past). Tomorrow he will be happy (future).","strategyClue":"Look for time indicator words like 'yesterday', 'now', or 'tomorrow' at the beginning or end of the sentence to decide if you need a past, present, or future verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0045","version":2,"contentHash":"sha256:88e2072b4287844ff2446371de2b872d2a1a1fbc257167fc7289be1af3a944cc","question":"Choose the correcthelping verbs. She __________ happy all day.","choices":["have been","had being","has been","having be"],"correct":2,"explanation":{"correct":"Answer: has been. The subject 'She' is singular, so it must be paired with the singular form 'has'. 'Has been' correctly expresses that she was and continues to be happy.","incorrect":[{"choice":"have been","category":"subject-verb disagreement","reason":"The verb 'have' is used for plural subjects like 'they' or 'we', but 'she' is singular. Therefore, 'have' does not match the subject."},{"choice":"had being","category":"incorrect verb form","reason":"The word 'being' is a participle and cannot follow 'had' in this way. 'Had been' would be grammatically possible for the past tense, but 'had being' is not a standard verb phrase."},"",{"choice":"having be","category":"incorrect verb form","reason":"This phrase is grammatically incorrect because 'be' should be in the past participle form 'been' when used after 'having'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":45,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":46,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"The verb 'to have' changes form to match the subject: use 'has' for singular subjects (he, she, it) and 'have' for plural subjects (they, we, you, I).","example":"She has been here; They have been here; He has finished; We have finished.","strategyClue":"Identify the subject of the sentence first. Ask yourself if the subject is singular (one person/thing) or plural (more than one) before selecting the correct form of 'to have'.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0046","version":2,"contentHash":"sha256:6d88f931f48ffa8d149957226a3c1735139bf782cec644fc036c914ac0f96802","question":"In the sentence below, which word is a verb? Bill and Tom ordered two cheeseburgers each.","choices":["Bill","cheeseburgers","ordered","each"],"correct":2,"explanation":{"correct":"Answer: ordered. A verb is a word that describes an action. In this sentence, 'ordered' is the action that Bill and Tom performed.","incorrect":[{"choice":"Bill","category":"proper noun","reason":"'Bill' is a person's name, which makes it a noun, not an action word."},{"choice":"cheeseburgers","category":"common noun","reason":"'Cheeseburgers' is the name of a thing, which makes it a noun, not an action word."},"",{"choice":"each","category":"determiner","reason":"'Each' is used to talk about individual items, but it does not represent an action being performed by the subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":46,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":49,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A verb is a word that shows action, occurrence, or a state of being.","example":"He runs (action), She feels happy (state of being), They jump (action).","strategyClue":"Ask yourself: 'What is the subject of the sentence doing?' Look for the word that identifies the physical or mental activity happening in the sentence.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0047","version":2,"contentHash":"sha256:00ddf4b9c06f6570bc2202a319acb29c5a21ee8344e91c25912b0ddded0109f5","question":"Which sentence is past tense?","choices":["I played baseball.","I play baseball.","I am playing baseball.","I will be playing baseball."],"correct":0,"explanation":{"correct":"Answer: I played baseball. The verb 'played' ends with '-ed', which indicates that the action happened in the past.","incorrect":["",{"choice":"I play baseball.","category":"present tense verb","reason":"The word 'play' shows an action happening in the present or as a regular habit, not something that has already finished."},{"choice":"I am playing baseball.","category":"present continuous tense","reason":"Using 'am playing' describes an action happening right now. It does not show that the action is completed."},{"choice":"I will be playing baseball.","category":"future tense verb","reason":"The word 'will' indicates that the action is going to happen in the future, not that it already took place."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":47,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":7,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Past tense verbs describe actions that have already happened, often by adding '-ed' to the end of a word.","example":"jump -> jumped, walk -> walked, cook -> cooked","strategyClue":"Look at the verb in each sentence and ask yourself, 'Did this happen yesterday?' Only the verb that shows the action is finished will be in the past tense.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0048","version":3,"contentHash":"sha256:37a7f0d29fedd5147a789a240d775dea5991efc425d261017867c1ee55525252","question":"Choose the best missing word. Th is morning, the bird _____ a stick for its nest.","choices":["find","finding","finds","found"],"correct":3,"explanation":{"correct":"Answer: found. Since the sentence begins with 'This morning', the action happened in the past. We use the past tense 'found' to show the event is already over.","incorrect":[{"choice":"find","category":"incorrect verb tense","reason":"The word 'find' is in the present tense, but the sentence describes something that happened this morning in the past."},{"choice":"finding","category":"missing helping verb","reason":"'Finding' is a participle that needs a helping verb like 'was' to describe a past action. On its own, it does not fit the sentence structure."},{"choice":"finds","category":"subject-verb disagreement","reason":"'Finds' is for actions happening right now, but the context 'This morning' indicates the action is finished."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":48,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":13,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Past tense verbs describe actions that have already happened. Most past tense verbs end in '-ed', but some 'irregular' verbs change their spelling entirely.","example":"jumped (past of jump), found (past of find), ate (past of eat)","strategyClue":"Look at the time indicator in the sentence. If the event happened earlier today, yesterday, or long ago, you must choose the version of the verb that describes a completed action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-verb-forms-q0049","version":2,"contentHash":"sha256:bf0e908df86c4e1eead5d362e2ba118ae241a4c68df55559bd53df6e71793c8c","question":"Which word correctly completes the sentence? The storm blew in _____.","choices":["later","yesterday","tomorrow","now"],"correct":1,"explanation":{"correct":"Answer: yesterday. The sentence refers to a storm that has already 'blew' (the past tense of blow), so we must use a time word that indicates a past event.","incorrect":[{"choice":"later","category":"incorrect verb tense","reason":"Since the sentence uses the past tense verb 'blew', using 'later' creates a conflict in time. We need a word that describes a finished action."},"",{"choice":"tomorrow","category":"future time reference","reason":"The word 'tomorrow' refers to the future. Because 'blew' is past tense, 'tomorrow' does not fit with the timeline of the sentence."},{"choice":"now","category":"present time reference","reason":"'Now' refers to the current moment. Because the action already happened, 'now' contradicts the past tense verb 'blew'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":49,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":16,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Time words act as clues to help the reader understand when an action took place. Past tense verbs require words that point to time already gone by.","example":"He walked yesterday (past). He is walking now (present). He will walk tomorrow (future).","strategyClue":"Look at the verb in the sentence. Ask yourself, 'Is this action happening right now, will it happen later, or did it already happen?' Choose the time word that matches the verb's tense.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0050","version":2,"contentHash":"sha256:b3a5d6fedf60552157cd81b88cf1b447c5bb3b460cd48b5c77df89aa301314eb","question":"Which word shows that a person is upset?","choices":["joyful","bold","frustrated","loving"],"correct":2,"explanation":{"correct":"Answer: frustrated. The word 'frustrated' describes a feeling of being annoyed or upset because you cannot change something or do what you want.","incorrect":[{"choice":"joyful","category":"positive emotion","reason":"This word describes being very happy or full of joy, which is the opposite of being upset."},{"choice":"bold","category":"personality trait","reason":"Being bold means being brave or confident. It does not describe how someone feels when they are upset or angry."},"",{"choice":"loving","category":"affectionate emotion","reason":"This word describes feeling deep care or affection for someone else. It does not mean a person is upset."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":50,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":36,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Words that describe how someone feels are called adjectives. We look for clues in sentences that show if a feeling is positive (happy) or negative (upset).","example":"He felt frustrated when his toy broke. She felt joyful when she won the game.","strategyClue":"Think about whether the word represents a 'thumbs up' feeling or a 'thumbs down' feeling to help identify if the emotion is negative like being upset.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0051","version":2,"contentHash":"sha256:93d8b811e1bf5898f8c9c60e81fcf00310190bb9d2be6009a0864667ea2872b6","question":"Identify the gerund phrase.","choices":["Elaina’s job was cleaning her room.","While cleaning her room, Elaina became ill.","Elaina cleaned her room.","Elaina was told to clean her room."],"correct":0,"explanation":{"correct":"Answer: Elaina’s job was cleaning her room. A gerund phrase consists of a gerund (an -ing verb acting as a noun) plus its modifiers and objects. In this sentence, 'cleaning her room' functions as the subject complement (the job), making it a gerund phrase.","incorrect":["",{"choice":"While cleaning her room, Elaina became ill.","category":"participial phrase","reason":"Here, 'cleaning her room' is a participial phrase because it describes Elaina, the person performing the action, rather than acting as a noun."},{"choice":"Elaina cleaned her room.","category":"verb phrase","reason":"This sentence uses 'cleaned' as a standard past-tense verb to describe Elaina's action, not as a noun phrase."},{"choice":"Elaina was told to clean her room.","category":"infinitive phrase","reason":"'To clean' is an infinitive phrase (to + verb), not a gerund phrase (verb ending in -ing acting as a noun)."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":51,"sourceFile":"Basic-4_Writing strategies_Application_Style.pdf","sourceQuestionNumber":5,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A gerund is a verb ending in -ing that functions as a noun. A gerund phrase includes the gerund and all its related words.","example":"Running is fun (gerund). I enjoy running marathons (gerund phrase).","strategyClue":"Test if the -ing phrase can be replaced by the word 'it' or 'something'. If the sentence still makes sense and the phrase is acting as a thing or activity, it is likely a gerund phrase.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0052","version":2,"contentHash":"sha256:317120239696bc42c6106116d9c0f864ec67b9f535295957f4e373e31405948a","question":"Which sentence includes an appositive?","choices":["The principal thanked the members of the Art Club.","Our class wenton a field trip on Monday.","We cast members have a dress rehearsal tonight.","We met after school to decorate the gym."],"correct":2,"explanation":{"correct":"Answer: We cast members have a dress rehearsal tonight. An appositive is a noun or noun phrase that renames or identifies the noun right next to it. Here, 'cast members' renames 'We', providing more information about the subject.","incorrect":[{"choice":"The principal thanked the members of the Art Club.","category":"prepositional phrase","reason":"The phrase 'of the Art Club' acts as a prepositional phrase describing which members, not as a noun phrase renaming 'members'."},{"choice":"Our class wenton a field trip on Monday.","category":"simple predicate","reason":"This sentence contains a subject and a verb describing an action, but there is no noun phrase placed right next to another noun to rename it."},"",{"choice":"We met after school to decorate the gym.","category":"infinitive phrase","reason":"The phrase 'to decorate the gym' is an infinitive phrase explaining why 'we met', not an appositive renaming the subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":52,"sourceFile":"Proficient-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":3,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An appositive is a noun or group of words that sits next to another noun to rename or describe it specifically.","example":"My friend Sarah (appositive) is funny. We students (appositive) studied hard.","strategyClue":"Look for a noun that is immediately followed by a phrase in the subject position that re-identifies who or what the subject is. Try removing the phrase; if the sentence still makes sense without it, it is likely an appositive.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0053","version":2,"contentHash":"sha256:814d41d412feb903ad6e2635b98acff4c90f1a64da7221ab1fd53e1285387407","question":"Which is the past tense form of the verb paint? Nancy paint the picture using her new watercolor paint s.","choices":["p aints","painting","will paint","painted"],"correct":3,"explanation":{"correct":"Answer: painted. The suffix '-ed' is added to the base verb 'paint' to indicate that the action happened in the past.","incorrect":[{"choice":"p aints","category":"present tense suffix","reason":"Adding '-s' creates the present tense, which describes things happening right now or regularly, not things that have already finished."},{"choice":"painting","category":"present participle","reason":"Adding '-ing' describes an ongoing action. For this sentence to work with 'painting', it would need a helper verb like 'was' before it."},{"choice":"will paint","category":"future tense","reason":"'Will paint' describes an action that has not happened yet. Since Nancy finished the picture, you need the past tense form."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":53,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":22,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To change most regular verbs into the past tense, you add the suffix '-ed' to the end of the base word.","example":"jump -> jumped, walk -> walked, cook -> cooked","strategyClue":"Ask yourself: 'Did this happen yesterday?' If the action is finished, choose the word that indicates it already occurred.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0054","version":2,"contentHash":"sha256:29a5314ec7d8800a57e4758ebc9830569a4d8831661c2d1e189eeaa02f3aa148","question":"In which sentence is an irregular past tense form of a verb used?","choices":["At the endof the ceremony, all the guests will have cake and ice cream.","The bird sang from its perch on the rooftop.","The farmer will harvest his crop in late November.","Sadie always bakes cookies for Maggie, her best friend."],"correct":1,"explanation":{"correct":"Answer: The bird sang from its perch on the rooftop. The word 'sang' is the irregular past tense of the verb 'sing,' meaning it does not follow the standard rule of adding '-ed' to show past action.","incorrect":[{"choice":"At the endof the ceremony, all the guests will have cake and ice cream.","category":"future tense verb","reason":"This sentence uses 'will have,' which is future tense rather than past tense. It describes something that hasn't happened yet."},"",{"choice":"The farmer will harvest his crop in late November.","category":"future tense verb","reason":"The word 'will harvest' is a future tense verb phrase. It describes an action that will occur later, not one that has already happened."},{"choice":"Sadie always bakes cookies for Maggie, her best friend.","category":"present tense verb","reason":"The verb 'bakes' is in the present tense, showing that Sadie performs this action regularly, not that she completed it in the past."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":54,"sourceFile":"Proficient-1_language Usage.pdf","sourceQuestionNumber":25,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Regular verbs form the past tense by adding '-ed' to the end, while irregular verbs change their spelling completely or stay the same.","example":"Regular: walk -> walked, jump -> jumped. Irregular: sing -> sang, eat -> ate, buy -> bought.","strategyClue":"Look for verbs that describe an action already completed. Once you find the action, check if it ends in '-ed' or if it changed its spelling entirely to show it happened in the past.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0055","version":3,"contentHash":"sha256:3e93ba25a40634bbf22984eda8437aeba94348970819e2931b0cca1eae1caf26","question":"Which sentence does not have an action verb?","choices":["Wilbur slept until noon yesterday.","The student talked to the teacher.","The wagon is old and broken.","Our horse eats hay every day."],"correct":2,"explanation":{"correct":"Answer: The wagon is old and broken. An action verb describes an activity someone or something is doing. In this sentence, 'is' is a linking verb that connects the subject to an adjective rather than describing an action.","incorrect":[{"choice":"Wilbur slept until noon yesterday.","category":"action verb included","reason":"'Slept' is an action verb because it describes the activity Wilbur was doing."},{"choice":"The student talked to the teacher.","category":"action verb included","reason":"'Talked' is an action verb because it describes what the student was doing."},"",{"choice":"Our horse eats hay every day.","category":"action verb included","reason":"'Eats' is an action verb because it describes the physical action the horse is performing."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":55,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":3,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Action verbs describe physical or mental activities that a person or thing can perform.","example":"Action: The dog ran (ran). Linking: The dog is tired (is).","strategyClue":"Ask yourself if the verb in the sentence describes a task that can be physically demonstrated or performed. If the word simply describes a state of being or existence, it is not an action verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0056","version":2,"contentHash":"sha256:cf58c5157d8f489c94abd9524dca4b1ba54d926cd59f22d9201245379449daf6","question":"Which sentence uses an irregular verb?","choices":["Janey skips to school.","The squirrel collects nuts.","Francie kicks the soccer ball.","Mom drives to work every day."],"correct":3,"explanation":{"correct":"Answer: Mom drives to work every day. The verb 'drives' is irregular because its past tense is 'drove,' not 'drived.' Regular verbs form their past tense by adding '-ed,' but irregular verbs change their spelling in the past tense.","incorrect":[{"choice":"Janey skips to school.","category":"regular verb","reason":"The verb 'skips' is regular because its past tense is simply 'skipped.' You only add '-ed' to the base form."},{"choice":"The squirrel collects nuts.","category":"regular verb","reason":"The verb 'collects' is a regular verb because you can form the past tense by adding '-ed' to make 'collected.'"},{"choice":"Francie kicks the soccer ball.","category":"regular verb","reason":"The verb 'kicks' follows the rule for regular verbs because the past tense is 'kicked,' formed by adding '-ed' to the verb."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":56,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":7,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Regular verbs add '-ed' to show the past tense, while irregular verbs do not follow this rule and often change their spelling completely.","example":"Regular: walk -> walked, talk -> talked; Irregular: drive -> drove, eat -> ate","strategyClue":"Try adding '-ed' to the end of each verb. If the word sounds correct and follows common spelling rules, it is likely a regular verb; if it sounds strange, it is an irregular verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0057","version":2,"contentHash":"sha256:2ad31797922906d7a11de3fcbf3559f3abf7b58b8da7ebfb8fcb571dc4333479","question":"Which sentence needs a helping verb?","choices":["She call a vet to help her.","He jumps on the couch.","They wrestled with the dog.","The alarm beeps every morning."],"correct":0,"explanation":{"correct":"Answer: She call a vet to help her. This sentence is incorrect because the subject 'she' needs a helping verb like 'did' or 'will' to make the action grammatically complete and show the correct tense.","incorrect":["",{"choice":"He jumps on the couch.","category":"correct verb tense","reason":"This sentence is already complete. 'Jumps' is a simple present tense verb that matches the singular subject 'he' correctly."},{"choice":"They wrestled with the dog.","category":"past tense verb","reason":"This sentence is grammatically correct as written. 'Wrestled' shows the action already happened and does not need a helper."},{"choice":"The alarm beeps every morning.","category":"subject-verb agreement","reason":"This sentence is already complete. 'Beeps' is the correct form of the verb for the singular subject 'the alarm' in the present tense."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":57,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":11,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A helping verb (like is, am, are, was, were, did, or will) works with a main verb to show when an action happens or to complete the meaning of a sentence.","example":"She is running (correct) vs. She running (incorrect); They did eat (correct) vs. They eat (incomplete meaning).","strategyClue":"Try reading each sentence aloud and ask if the action word is clearly showing the right timing. If the sentence feels unfinished or like it is missing a 'link' to the past or future, it likely needs a helping verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0058","version":2,"contentHash":"sha256:540d700d7d014f721f3718a0fda8f6c747dda61724bf43f27ce07250eb3720bb","question":"Choose the best linking verb to complete the sentence below. The pepper _____ too spicy to me.","choices":["tastes","acts","feels","are"],"correct":0,"explanation":{"correct":"Answer: tastes. Linking verbs connect the subject to a word that describes it. Since a pepper is something you eat, 'tastes' is the most logical linking verb to describe the sensory experience of the pepper.","incorrect":["",{"choice":"acts","category":"improper verb usage","reason":"While 'acts' is a verb, it describes a behavior or performance. Peppers do not perform actions, so it does not make sense in this context."},{"choice":"feels","category":"inaccurate sensory verb","reason":"While 'feels' is a linking verb, it refers to texture or temperature. 'Spicy' describes a flavor, so 'tastes' is the correct sensory verb to use."},{"choice":"are","category":"subject-verb disagreement","reason":"The subject 'The pepper' is singular, so the plural verb 'are' cannot be used. You must use a singular verb form to match the singular subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":58,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":19,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Linking verbs connect a subject to a word that describes or identifies it, rather than showing an action. They often describe senses like how something looks, tastes, or feels.","example":"The soup tastes salty. The sun feels warm. The cat is hungry.","strategyClue":"Ask yourself what part of the body you would use to experience the quality being described. If the sentence describes a flavor, choose the verb that relates to the mouth.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0059","version":2,"contentHash":"sha256:c9462c092fbdef962ed654bf10ff82a7c17e55a9d99fa33a3bd60400e3c86e6f","question":"What is the verb in this sentence? The short, tired, toddler slept late the next morning.","choices":["tired","slept","late","next"],"correct":1,"explanation":{"correct":"Answer: slept. The verb is the action word in a sentence. 'Slept' describes the action that the toddler performed.","incorrect":[{"choice":"tired","category":"adjective confusion","reason":"The word 'tired' is an adjective, not a verb. Adjectives describe nouns, while verbs describe actions or states of being."},"",{"choice":"late","category":"adverb identification","reason":"'Late' is an adverb telling us when the action happened. It does not describe the action itself."},{"choice":"next","category":"adjective identification","reason":"'Next' is an adjective modifying the noun 'morning.' It does not express an action or state of being."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sequence":59,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":46,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A verb is a word that tells us what a person, animal, or thing is doing, feeling, or being.","example":"Action: The cat jumped. State: She felt happy. Being: He is here.","strategyClue":"Ask yourself, 'What is the person or object doing?' The word that answers that question is the action verb.","link":"","linkText":""}},{"id":"grammar-verb-forms-q0060","version":2,"contentHash":"sha256:7a6ed87297ed60ab2d8c7592b6bb82c124635ecfbef62c160ee9f935143ccb48","question":"When writing, when should the modal auxiliary verb “must” be used?","choices":["to show strong obligation","to ask permission","to show ability","to give permission"],"correct":0,"explanation":{"correct":"Answer: to show strong obligation. The modal 'must' is used to express a necessity, a requirement, or something that is absolutely essential to do.","incorrect":["",{"choice":"to ask permission","category":"incorrect modal function","reason":"Asking for permission is typically done using modals like 'may' or 'can', rather than 'must'."},{"choice":"to show ability","category":"incorrect modal function","reason":"To express what someone is capable of doing, we use 'can' or 'could', not 'must'."},{"choice":"to give permission","category":"incorrect modal function","reason":"Giving permission uses 'may' or 'can'. Using 'must' would turn it into a strict command, not an offer of permission."}]},"studyAid":{"definition":"The modal verb 'must' is used to express that an action is necessary or required by law or a person in charge.","example":"I must finish my homework tonight. You must wear your seatbelt in the car.","strategyClue":"Ask yourself if the sentence is about having a choice, being able to do something, or if it is a strict rule that cannot be ignored.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 1_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":60,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0061","version":2,"contentHash":"sha256:51177681ff636cf24971c7db7275a6ea12f7956bf9ae2c54752607875bb5d2d7","question":"Choose the sentence that has the proper progressive verb tense.","choices":["Bill, Joey, and Andy have played basketball next spring.","Two of my four turtles might out of the yard tomorrow night.","Ninety-ve cents are too much to charge for a cookie.","Millie, Samantha, and Jolene are singing the alphabet song to Mary right now."],"correct":3,"explanation":{"correct":"Answer: Millie, Samantha, and Jolene are singing the alphabet song to Mary right now. This sentence uses the present progressive tense ('are singing') to show an action happening at this exact moment.","incorrect":[{"choice":"Bill, Joey, and Andy have played basketball next spring.","category":"tense inconsistency","reason":"The phrase 'have played' describes the past, but 'next spring' is in the future. These two parts do not fit together."},{"choice":"Two of my four turtles might out of the yard tomorrow night.","category":"missing verb","reason":"This sentence is missing an action word. Without a verb like 'might get' or 'might jump', there is no progressive tense present."},{"choice":"Ninety-ve cents are too much to charge for a cookie.","category":"subject-verb disagreement","reason":"When talking about a specific amount of money as a single total, use the singular 'is' rather than the plural 'are'."},""]},"studyAid":{"definition":"Progressive verb tenses describe ongoing actions. They are formed by using a helping verb (like 'is', 'are', or 'was') followed by a main verb ending in '-ing'.","example":"He is running. They are eating. She was sleeping.","strategyClue":"Look for the '-ing' action word and verify that the helping verb makes sense with the time frame mentioned in the sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 1_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":4,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":61,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0062","version":2,"contentHash":"sha256:da8027ae0ced72fdcc31874386d07ee964b3617f85c930f46f4aff00b9b21115","question":"Choose the sentence that contains a modal auxiliary verb.","choices":["You are a very good runner.","Mark is having a good time at the birthday party.","I am not a big fan of mashed potatoes.","You could be a really good soccer player if you applied yourself and practiced more."],"correct":3,"explanation":{"correct":"Answer: You could be a really good soccer player if you applied yourself and practiced more. The word 'could' is a modal auxiliary verb because it expresses possibility or ability and is used with another verb ('be').","incorrect":[{"choice":"You are a very good runner.","category":"stative linking verb","reason":"The word 'are' is a form of the verb 'to be' used as a linking verb here, not a modal auxiliary verb. It shows a state of being, not possibility or necessity."},{"choice":"Mark is having a good time at the birthday party.","category":"present progressive tense","reason":"The word 'is' acts as an auxiliary verb for the present continuous tense, but it is not a modal verb. Modal verbs like 'can', 'could', or 'should' change the mood of the main verb."},{"choice":"I am not a big fan of mashed potatoes.","category":"linking verb usage","reason":"The word 'am' is a linking verb used to connect the subject to an adjective or noun. It does not function as a modal auxiliary that shows possibility, permission, or obligation."},""]},"studyAid":{"definition":"Modal auxiliary verbs are special helping verbs that show possibility, permission, ability, or necessity. They are always used before another main verb.","example":"He can swim (ability). You should study (advice). It might rain (possibility).","strategyClue":"Look for verbs like 'can', 'could', 'may', 'might', 'must', 'shall', 'should', 'will', or 'would'. Test if the word adds a meaning of 'possibility' or 'need' to the main action in the sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 1_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":62,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0063","version":3,"contentHash":"sha256:89b06360c803412bc8ea9a3969e168471bcbb3f452b12ea1b59ef80540d6e312","question":"What would transform this fragment into a complete sentence? Five ways to make electricity.","choices":["Replacing the period with a question mark at the end of the sentence.","Adding “: generators, steam, hydroelectric, windmill and solar power” to the end of the sentence.","Adding “There are” to the beginning of the sentence.","Nothing. This sentence is complete already."],"correct":2,"explanation":{"correct":"Answer: Adding “There are” to the beginning of the sentence. A complete sentence must have a subject and a verb that expresses a complete thought; starting with “There are” provides the missing subject and verb required to turn the fragment into a full, independent clause.","incorrect":[{"choice":"Replacing the period with a question mark at the end of the sentence.","category":"improper terminal punctuation","reason":"Changing the punctuation does not fix the underlying problem. The words 'Five ways to make electricity' still lack a verb, so it remains a fragment regardless of the ending mark."},{"choice":"Adding “: generators, steam, hydroelectric, windmill and solar power” to the end of the sentence.","category":"extended list fragment","reason":"Adding a list of nouns simply makes the fragment longer, but it still does not provide the action or state of being needed to make the sentence complete."},"",{"choice":"Nothing. This sentence is complete already.","category":"missing sentence parts","reason":"The group of words 'Five ways to make electricity' is a noun phrase, not a sentence, because it does not tell us what those five ways are doing or what is happening to them."}]},"studyAid":{"definition":"A complete sentence needs both a subject (who or what the sentence is about) and a predicate (the verb or action). If a group of words lacks these, it is a fragment.","example":"Fragment: Five ways to run. / Complete: There are five ways to run.","strategyClue":"Ask yourself: 'What is happening?' or 'What is the action in this sentence?' If you cannot find a verb that explains what the subject is doing, the group of words is likely a fragment.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 1_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":8,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":63,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0064","version":2,"contentHash":"sha256:dcae83c9662430c26159c220508ab06111888953e6cb79d53ee210d7883360ea","question":"Which of the following sentences correctly uses a modal auxiliary verb? You really ______ see that lm because it is so good","choices":["can","may","shall","must"],"correct":3,"explanation":{"correct":"Answer: must. 'Must' is a modal auxiliary verb used to express a strong recommendation or necessity, which fits the context of suggesting someone see a great film.","incorrect":[{"choice":"can","category":"modal verb meaning","reason":"While 'can' is a modal verb, it is used for ability. 'Must' is more appropriate here to emphasize the strong recommendation that the listener should experience the good film."},{"choice":"may","category":"modal verb usage","reason":"'May' is typically used for permission or possibility. It does not convey the same strong sense of enthusiasm or requirement as 'must' does in this sentence."},{"choice":"shall","category":"formal modal usage","reason":"'Shall' is usually reserved for formal offers or future predictions. It sounds unnatural in a friendly recommendation about a good movie."},""]},"studyAid":{"definition":"Modal verbs are helper verbs that show possibility, ability, or necessity. They change the 'mood' of the main verb that follows them.","example":"I can swim (ability). You must try this (necessity). We may go later (possibility).","strategyClue":"Think about the intent of the sentence: is it describing an ability, a possibility, or a strong suggestion? Choose the modal that best matches that feeling.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 2_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":64,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0065","version":2,"contentHash":"sha256:8b12e7c8e0dba4729305a1adfa04cb9be68466c1987bef140e7e92ba6effb969","question":"Choose the sentence that contains a modal auxiliary verb.","choices":["Jeremiah has potential to be an excellent mathematician.","I shall never say another bad word again.","Mariah is the most talented player on theroster.","Juliet is eating breakfast for dinner."],"correct":1,"explanation":{"correct":"Answer: I shall never say another bad word again. The word 'shall' is a modal auxiliary verb, which is a type of helping verb used to express necessity, possibility, or willingness.","incorrect":[{"choice":"Jeremiah has potential to be an excellent mathematician.","category":"main verb misuse","reason":"'Has' is used here as a main verb to show possession or status, not as an auxiliary verb helping another action word."},"",{"choice":"Mariah is the most talented player on theroster.","category":"state of being","reason":"'Is' is a linking verb used here to describe Mariah, but it is not functioning as an auxiliary verb to another verb."},{"choice":"Juliet is eating breakfast for dinner.","category":"present participle auxiliary","reason":"While 'is' is an auxiliary verb, it is a primary auxiliary verb (to be) rather than a modal auxiliary verb (like can, should, must, or shall)."}]},"studyAid":{"definition":"Modal auxiliary verbs are special helping verbs that add meaning to the main verb, such as ability, permission, or obligation. Common examples include can, could, may, might, must, shall, should, will, and would.","example":"I can swim. (ability), You should study. (advice), He will arrive soon. (certainty)","strategyClue":"Look for a verb that helps the main action word but does not change its form (no -ing or -ed endings). Identify the word that expresses possibility or necessity rather than just describing a state of being.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 2_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":65,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0066","version":3,"contentHash":"sha256:59c37c9b1d31651e53b17a30b4ab49e80a36068b437b1e27c7bcc7b2dbae294d","question":"Which of the following sentences correctly shows present progressive tense?","choices":["Our cheer team would plan a trip to Disney Land.","Our cheer team is planning a trip to Disney Land.","Our cheer team might plan a trip to Disney Land.","Our cheer team will be planning a trip to Disney Land."],"correct":1,"explanation":{"correct":"Answer: Our cheer team is planning a trip to Disney Land. The present progressive tense uses the helping verb 'is', 'am', or 'are' combined with a verb ending in '-ing' to show an action currently in progress.","incorrect":[{"choice":"Our cheer team would plan a trip to Disney Land.","category":"conditional mood error","reason":"'Would' is used for conditional actions, not for things happening right now. It does not show the ongoing nature of the present progressive."},"",{"choice":"Our cheer team might plan a trip to Disney Land.","category":"modal verb usage","reason":"'Might' shows possibility or uncertainty. It describes a potential future event rather than a current, ongoing activity."},{"choice":"Our cheer team will be planning a trip to Disney Land.","category":"future progressive tense","reason":"'Will be planning' describes an action that will happen in the future. Present progressive tense focuses on actions happening at this very moment."}]},"studyAid":{"definition":"The present progressive tense describes actions happening right now by using 'am', 'is', or 'are' plus a verb that ends in '-ing'.","example":"He is running (correct) vs. He runs (simple present); They are eating (correct) vs. They eat (simple present).","strategyClue":"Look for the sentence that uses a 'to be' verb combined with an action verb ending in '-ing'. Ask yourself if the sentence describes an action happening at this exact moment.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 3_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":66,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0067","version":2,"contentHash":"sha256:7c441bf23965c29cddebc54c2db971799e1be4a748ecdb21e4b00e139315b12f","question":"What would transform the fragment into a complete sentence? A really nice set of dishes.","choices":["A really nice set of dishes, twelve sets of silverwa re, and twelve glasses.","A really nice set of dishes will be great to have for Thanksgiving.","Doesn’t really need a nice set of dishes.","My grandmother’s really nice set of dishes."],"correct":1,"explanation":{"correct":"Answer: A really nice set of dishes will be great to have for Thanksgiving. A complete sentence must contain both a subject and a predicate (a verb phrase that says what the subject is doing or being). This option adds the verb 'will be' to create a complete thought.","incorrect":[{"choice":"A really nice set of dishes, twelve sets of silverwa re, and twelve glasses.","category":"fragment list","reason":"This is just a long list of items (a noun phrase). Even though it is long, it lacks a verb to tell us what is happening with these items."},"",{"choice":"Doesn’t really need a nice set of dishes.","category":"missing subject","reason":"This sentence is missing a subject; we don't know who or what 'doesn't need' the dishes. A complete sentence needs a 'who' or 'what'."},{"choice":"My grandmother’s really nice set of dishes.","category":"possessive noun phrase","reason":"This is a noun phrase, not a sentence. Adding 'My grandmother's' describes who owns the dishes, but still fails to provide a verb to complete the action or state of being."}]},"studyAid":{"definition":"A complete sentence needs two main parts: a subject (who or what the sentence is about) and a predicate (a verb that describes an action or state of being).","example":"Fragment: The tired cat. Sentence: The tired cat slept on the rug. Fragment: Ran to the park. Sentence: She ran to the park.","strategyClue":"Read each option and ask, 'What is the action in this sentence?' If you cannot find a word that shows action or a state of being linked to the subject, the phrase is likely a fragment.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Advanced Quiz 3_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":67,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0068","version":2,"contentHash":"sha256:e0c3e26c53e616d10fb0c15b2a526f2e36a618c7792c4ef1e8d426ebd64115f2","question":"Choose the correct modal auxiliary to complete the following sentence. You ________ stay up late with your parent’s permission.","choices":["must","may","can","none of the above"],"correct":2,"explanation":{"correct":"Answer: can. The modal 'can' is used to express that someone has permission to do something. Since the sentence mentions having permission from a parent, 'can' is the correct choice.","incorrect":[{"choice":"must","category":"incorrect modal meaning","reason":"Using 'must' changes the meaning to a requirement or obligation. 'Must' does not express permission, which is what the sentence context requires."},{"choice":"may","category":"formal permission","reason":"While 'may' can indicate permission, 'can' is more commonly used in casual, everyday contexts. Between the choices provided, 'can' is the most direct fit for the permission described here."},"",{"choice":"none of the above","category":"missing modal","reason":"Because 'can' correctly fits the definition of expressing permission within the sentence structure, this choice is incorrect."}]},"studyAid":{"definition":"Modal verbs are helper verbs that express ability, permission, or necessity. 'Can' and 'may' are both used to describe permission.","example":"You can play outside now. (Permission) You must wash your hands. (Necessity) I can ride a bike. (Ability)","strategyClue":"Look at the sentence and identify if the speaker is talking about a rule, an ability, or someone being allowed to do something. Once you identify the purpose, pick the word that best matches that feeling.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Basic Quiz 1_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":6,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":68,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0069","version":2,"contentHash":"sha256:2e0ab707d8b288648572586303fad01d75282e805f3ae0daff145cd6c3c8367a","question":"Which word correctly completes the following sentence? I know that Ying Yue ______ speak Chinese and English well.","choices":["might","can","are","weren’t"],"correct":1,"explanation":{"correct":"Answer: can. The word 'can' is a modal verb used to express ability or capability. In this sentence, it correctly describes Ying Yue's skill in speaking two languages.","incorrect":[{"choice":"might","category":"modal verb meaning","reason":"The word 'might' expresses possibility or doubt, not certainty of ability. Use 'can' instead to state that she definitely has the skill to speak these languages."},"",{"choice":"are","category":"subject-verb disagreement","reason":"The verb 'are' is a linking verb that does not fit before the base form 'speak'. You need a modal verb here to express ability."},{"choice":"weren’t","category":"incorrect verb tense","reason":"The word 'weren’t' is a past tense contraction that suggests she no longer speaks the languages. It also does not fit grammatically before the verb 'speak' in this context."}]},"studyAid":{"definition":"Modal verbs like 'can' are helper words used to express ability, permission, or possibility. They do not change form regardless of the subject.","example":"I can jump high. (Ability) / She can swim well. (Ability) / They can play soccer. (Ability)","strategyClue":"Look at the main action word in the sentence. Decide if you are describing a proven skill or ability, then pick the helper word that specifically indicates being able to do that action.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Basic Quiz 3_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":69,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0085","version":2,"contentHash":"sha256:cbfad75c9045413aa48807c2374438e94d7a5f8dba8b53159a91888fd7a878c3","question":"Choose the correct modal auxiliary to complete the following sentence. ____________ I borrow your pencil?","choices":["M ust","May","Can","None of the above"],"correct":1,"explanation":{"correct":"Answer: May. 'May' is the correct choice because it is the polite and formal way to ask for permission. When asking someone else to lend you an object, 'May' is preferred in standard English.","incorrect":[{"choice":"M ust","category":"incorrect modal meaning","reason":"The word 'must' implies a command or a strong requirement. Since borrowing a pencil is a polite request, 'must' makes the sentence sound like you are forcing the person to give you the pencil."},"",{"choice":"Can","category":"informal modal choice","reason":"While 'can' is often used in casual conversation, it actually asks about the person's physical ability to lend the pencil. 'May' is the better choice for asking for formal permission."},{"choice":"None of the above","category":"multiple choice logic","reason":"This is incorrect because 'May' is a standard and grammatically correct option provided in the original prompt choices."}]},"studyAid":{"definition":"Modal auxiliaries are helping verbs that express possibility, permission, or ability. 'May' is used to ask for permission politely.","example":"May I go to the restroom? (Polite) vs. Can I go to the restroom? (Informal/Ability)","strategyClue":"Think about the tone of your sentence. If you are asking for permission to do something, look for the word that sounds most polite and respectful.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["verbs","verb tense","grammar and usage","language","grade 4"],"feedbackFocus":"use the grammar rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Proficient Quiz 3_Language_Grammar and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"grammar-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":85,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0070","version":2,"contentHash":"sha256:82120b237eaf5c2eccbe9ad0c516cd851ce8e0cbed9c778d15cffdd4aadc736f","question":"Wh is not a state of being word? ich word","choices":["was","look","am","be"],"correct":1,"explanation":{"correct":"Answer: look. 'Look' is an action verb because it describes something you do with your eyes, whereas 'was', 'am', and 'be' are state of being verbs that describe a condition or existence.","incorrect":[{"choice":"was","category":"state of being verb","reason":"The word 'was' is a form of the verb 'to be,' which describes a past state of being rather than a physical action."},"",{"choice":"am","category":"state of being verb","reason":"'Am' is a linking verb used to show a state of being in the present; it does not represent an action being performed."},{"choice":"be","category":"state of being verb","reason":"'Be' is the base form of the 'to be' family, which defines existence or identity instead of an action."}]},"studyAid":{"definition":"A state of being verb describes what something is, was, or will be, rather than a physical or mental action.","example":"Action: run, jump, think. State of Being: is, are, was, were, am, be.","strategyClue":"Try to act out the word. If you can physically perform the word (like 'running' or 'jumping'), it is an action verb, not a state of being verb.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["formal language","vocabulary and usage","language","grade 4"],"feedbackFocus":"use the word clue, word part, or usage rule to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Proficient Quiz 1_Language_Vocabulary and Usage_ MAP 4th Grade.pdf","sourceQuestionNumber":10,"sourceCategory":"vocabulary-and-usage","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":70,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0072","version":2,"contentHash":"sha256:b32aad247592c2f15e136c6b879ad9f67586cd53a3f6b2bbae511e853583991e","question":"When writing, when should the modal auxiliary verb “may not” be use d?","choices":["to show the opposite of must","to show the opposite of can","to show the opposite of may","none of the above"],"correct":2,"explanation":{"correct":"Answer: to show the opposite of may. The modal 'may' expresses permission or possibility, and adding 'not' creates the negative form of that specific verb.","incorrect":[{"choice":"to show the opposite of must","category":"incorrect verb negation","reason":"The opposite of 'must' is 'must not' or 'need not'. 'May not' relates specifically to the permission or possibility suggested by 'may'."},{"choice":"to show the opposite of can","category":"incorrect verb negation","reason":"The opposite of 'can' is 'cannot' or 'can't'. 'May' and 'can' are different modal verbs with distinct meanings."},"",{"choice":"none of the above","category":"incorrect choice","reason":"Since 'may not' is the direct negative form of 'may', the correct function is listed among the choices."}]},"studyAid":{"definition":"Modal auxiliary verbs help define the mood or intent of a sentence. Adding 'not' after a modal verb creates its negative form to show lack of permission or lack of possibility.","example":"I may go (permission) vs. I may not go (denial of permission); It may rain vs. It may not rain.","strategyClue":"Look at the modal verb used in the phrase 'may not'. Identify which base modal it is paired with, then consider if the negative word 'not' changes the meaning of that specific verb.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":13,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":72,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0073","version":3,"contentHash":"sha256:0a9112fc06221a793c12deff30b5692e36265eb0cece951eac606df928a4af73","question":"Choose the best modal auxiliary verb to complete the following sentence. You ________ not borrow my pencil, because I need it for my homework assignment that is due tomorrow.","choices":["mu st","can","may","none of the above"],"correct":2,"explanation":{"correct":"Answer: may. In this context, the speaker is denying permission. 'May not' is the standard way to express that someone does not have permission to do something.","incorrect":[{"choice":"mu st","category":"modal verb usage","reason":"While 'must' expresses obligation, 'must not' is used for strong prohibitions or rules, rather than denying a simple request for permission."},{"choice":"can","category":"permission vs. ability","reason":"'Can' is typically used to talk about ability. To grant or deny permission, 'may' is the formal choice preferred in this context."},"",{"choice":"none of the above","category":"incorrect option selection","reason":"One of the provided modal verbs fits the sentence perfectly to express the denial of permission."}]},"studyAid":{"definition":"Modal verbs are helper verbs used to express ideas like permission, ability, or necessity. 'May' is often used to talk about giving or refusing permission.","example":"You may go outside. (permission granted) / You may not touch that. (permission denied)","strategyClue":"Ask yourself if the sentence is about physical strength or about rules and permission. If it is about permission, choose the modal verb most commonly used to grant or deny it.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":40,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":73,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0214","version":2,"contentHash":"sha256:0be4433fe54db5cb5a528a7a3bfd105f97dc5f3e153873de0e13828b20d1bc1b","question":"Choose the modal auxiliary to complete the correct following sentence. I do my tax returns, or I will have to pay a penalty.","choices":["must","could","might","can"],"correct":0,"explanation":{"correct":"Answer: must. The word 'must' indicates a requirement or an obligation. Since there is a penalty for not doing the tax returns, the speaker is expressing a necessity.","incorrect":["",{"choice":"could","category":"modal of possibility","reason":"'Could' describes a possibility or an ability. Using it here makes the sentence sound like a choice rather than a requirement to avoid a penalty."},{"choice":"might","category":"modal of uncertainty","reason":"'Might' suggests that something is uncertain or unlikely. It does not carry the strong sense of obligation needed to avoid a penalty."},{"choice":"can","category":"modal of ability","reason":"'Can' refers to being able to do something. It does not convey the force of duty or legal requirement needed for tax returns."}]},"studyAid":{"definition":"Modal verbs of obligation tell us that something is necessary or required. Words like 'must' or 'have to' show that you have no other choice.","example":"You must wear a seatbelt. I must finish my homework before I can play. You have to be quiet in the library.","strategyClue":"Look at the consequence in the sentence. If there is a punishment or a negative outcome for not doing the action, look for the word that expresses a strict rule or requirement.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":10,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":214,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0232","version":3,"contentHash":"sha256:1deafbb25f88ef1d39b91e97c1db501e247906925fbfdad2903726e6b4d530ee","question":"Choose the correct verb tense. Matt and I in a tournament at Possum Kingdom Lake today.","choices":["are fishing","were fishing","did fish","have fished"],"correct":0,"explanation":{"correct":"Answer: are fishing. The sentence uses the word 'today,' which indicates an action is happening in the present. 'Are fishing' is the correct present continuous tense for the plural subject 'Matt and I'.","incorrect":["",{"choice":"were fishing","category":"past tense verb","reason":"The word 'today' tells us the action is happening now, not in the past. 'Were fishing' describes an action that happened previously."},{"choice":"did fish","category":"simple past tense","reason":"Using 'did fish' implies the action is already completed. Since the action is occurring today, you need a present tense verb form."},{"choice":"have fished","category":"present perfect tense","reason":"While this refers to the present, 'have fished' implies the action might be finished or happened at an unspecified time. 'Are fishing' correctly shows the action is currently in progress today."}]},"studyAid":{"definition":"Verb tenses show when an action happens. Present tense is used for things happening right now, while past tense is used for things that are already finished.","example":"Now: We are playing. Yesterday: We played. Today: We are walking. Yesterday: We walked.","strategyClue":"Look for time-clue words in the sentence like 'yesterday', 'tomorrow', or 'today' before deciding which verb tense to pick.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar and usage","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":28,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":232,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-verb-forms-q0136","version":2,"contentHash":"sha256:c5fc6199ea8042c5a5e6ba5ce08fc05b474625a552721eccfd4a44b3efe52204","question":"Which sentence contains an auxiliary verb? (1) Rena and her mother need to find a Christmas gift for Rena’s brother, Ahmed. (2) They discussed driving to their neighborhood Walmart, shopping on Amazon, or going to the mall to find his gift. (3) Because Rena’s mother had knee replacement surgery, I don’t think they will be going to a store to buy Ahmed’s gift. (4) They might decide it best to buy his gift online.","choices":["Sentence 1","Sentence 2 and","Sentence 3","Sentence 3 and 4"],"correct":3,"explanation":{"correct":"Answer: Sentence 3 and 4. Both sentences contain auxiliary verbs: sentence 3 includes 'will' (in 'will be going'), and sentence 4 includes 'might' (in 'might decide'). Auxiliary verbs help the main verb express tense or possibility.","incorrect":[{"choice":"Sentence 1","category":"missing auxiliary verb","reason":"Sentence 1 uses the main verb 'need,' but it does not use a helping or auxiliary verb to change its tense or mood."},{"choice":"Sentence 2 and","category":"incorrect choice format","reason":"Sentence 2 lists actions using gerunds ('driving,' 'shopping,' 'going') but does not contain an auxiliary verb to support them."},{"choice":"Sentence 3","category":"incomplete answer","reason":"While sentence 3 is correct, it is not the complete answer because sentence 4 also contains an auxiliary verb."},""]},"studyAid":{"definition":"An auxiliary verb (or helping verb) sits before a main verb to show tense, mood, or voice. Common ones include forms of 'be,' 'do,' 'have,' or modal verbs like 'can,' 'will,' and 'might.'","example":"She IS running. (is = auxiliary); They HAVE finished. (have = auxiliary); We CAN go. (can = auxiliary)","strategyClue":"Look for verbs that don't describe a physical action themselves but sit right before another verb to provide extra meaning. Check if the sentence has two verbs working together to express one main idea.","link":"https://www.grammar-monster.com/glossary/auxiliary_verbs.htm","linkText":"Grammar Monster - Auxiliary Verbs"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","verb forms","auxiliary verbs","language usage","language","grade 4"],"feedbackFocus":"identify helping verbs that work with a main verb to show tense, mood, or possibility","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"grammar-verb-forms","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":34,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":136,"skillIds":["grammar.usage"],"standardIds":["L.3-6.1"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
